// live/text_notes_ru.js: the notes found on the floors; generated by tools/notes_build.py from docs/notes/*.json, edit those.
(function (root) {
  (root.TEXT || (root.TEXT = {})).notes = [{"id":"cellar_001","kind":"note","title":"Записка в щели","text":"Кто бы ни держал соседний отсек, простите меня. За щелью в стене стоит ваша плошка с солью, я дотянулась до неё и взяла горсть. Моя соль вышла, лавка закрыта до пятницы, а муж и трое детей просят супа. Верну вам с горкой, честное слово, я не из тех, кто берёт без спроса. Гвен Марлоу, шестой подвал.","chain":"salt_loan","part":1},{"id":"cellar_002","kind":"note","title":"Список к свадьбе","text":"Том, вот что надо к свадьбе нашей Розы, и не перепутай. Купи шесть мер муки и изюма, сколько дадут. Скатерть я возьму у Гертруды и на этот раз верну её чистой, я ей поклялась. Жениха надо побрить, мальчик он хороший, но сам не догадается. Дядю Альберта мы не зовём, но ты же знаешь, какой он, всё равно придёт, так что хлеба бери ещё на двоих. Наша девочка выходит замуж, Том. Я плачу над этим списком, не смейся."},{"id":"cellar_003","kind":"note","title":"Наряд подмастерью","text":"Перси, сегодня сходи к Хобарту на Мельничную и поставь ему замок на подвальную дверь, снаружи, как теперь все ставят. Бери большой, он заплатит. Петли тоже смажь, его жена жаловалась, что дверь скрипит. Пирог на столе отнесёшь ему, это заказчику, и я его измерил, так что не вздумай отщипнуть. И надень шарф, на улице сыро, а лечить тебя мне не на что.","chain":"hobart_locks","part":1},{"id":"cellar_004","kind":"note","title":"Трактирный счёт","text":"Таверна «Три гуся», счёт господину Пику. Вы выпили пять кружек эля, а потом ещё пять. За беспокойство от вашего пения с вас две монеты, за сломанную скамью одна, за кружку, которая ушла с вами домой, полмонеты. Кружку прошу вернуть, она была у нас одна с ручкой, и жена моя по ней плачет. Пели вы, кстати, неплохо, пока не начали про козу. Хозяин Бен."},{"id":"cellar_005","kind":"note","title":"Продажа дома","text":"Продаётся дом на Кожевенной. Стены крепкие, печь новая, колодец во дворе, до рынка два шага. Цена ниже, чем вы думаете. Мы с женой прожили здесь сорок два года, и я бы никогда его не продал, будь она жива. Смотреть приходите только днём. Ключ возьмёте у соседки, потому что я там больше не ночую и вам не советую."},{"id":"cellar_006","kind":"note","title":"Школьная пропись","text":"Перепиши десять раз: я не буду кидать репу в мастера Кроуфорда. Я не буду кидать репу в мастера Кроуфорда. Я не буду кидать репу в мастера Кроуфорда. Я не буду кидать репу в мастера. Мастер Кроуфорд, я устал, дальше там всё то же самое, честное слово. Мама говорит, что вы хороший человек и что в ухо я попал вам нечаянно. Я попал нарочно, но вы правда хороший."},{"id":"cellar_007","kind":"note","title":"Молитва на ночь","text":"боже мама сказала что написанное доходит до тебя быстрей. сделай чтобы папа перестал кашлять. сделай чтобы Нэн отдала мою ленту только ругать её не надо она моя сестра. и пусть тот кто ходит у нас под полом ходит потише а то он будит малинького. аминь"},{"id":"cellar_008","kind":"note","title":"Записка в щели","text":"Соседка, соль я вернула, как обещала, и с горкой. Спасибо вам за яйцо, я его не просила, но оно крупное и свежее, и мы съели его за завтраком. Как вас зовут? Мне неловко писать вам, как чужой, мы ведь теперь почти родня по соли. Муж уверяет, что за этой стеной одна земля, а он сам клал тут полки, так что я уже не знаю, кому верить. Гвен.","chain":"salt_loan","part":2},{"id":"cellar_009","kind":"note","title":"Черновик эпитафии","text":"Мастеру камнерезу от вдовы Флинт. Прошу написать так: здесь лежит Бартоломью Флинт, кровельщик, упал только один раз. Он двадцать лет хвастался, что ни разу не падал, и я хочу, чтобы последнее слово осталось за мной. Заплатить я могу четыре монеты. Если буквы выйдут дороже, уберите слово кровельщик, все и так знали, кем он был. Мне его очень не хватает, но больше у меня нет."},{"id":"cellar_010","kind":"note","title":"Рецепт мази","text":"Милая Джейн, ты просила написать, чем я лечу паучьи укусы. Возьми ложку гусиного жира и истолки в нём подорожник. Мажь на ночь и завязывай чистой тряпкой. Если к утру укус перешёл на другое место, мазь уже не поможет, тогда зови лекаря Тиббета и заплати ему вперёд, иначе он не придёт, ты же знаешь, какой он жадина. Береги детей и пиши мне почаще. Твоя тётя Энн."},{"id":"cellar_011","kind":"note","title":"Правила приказчику","text":"Тоби, сыр режь при покупателе, чтобы никто не говорил, будто мы его подменяем. В долг Морганам не давай, и тем Морганам, что из соседнего дома, тоже. Если спросят, свежий ли сыр, отвечай, что принесли утром, а какое это было утро, уточнять необязательно. Дверцу в подпол на ночь запирай на крючок. Крючок у нас с этой стороны, а вчера утром он был откинут, и сделал это не я. И ешь как следует, ты совсем худой."},{"id":"cellar_012","kind":"note","title":"Наряд подмастерью","text":"Перси, Хобарт приходил опять и просит второй замок на ту же дверь, пониже первого. У человека завелись либо деньги, либо крысы. Деньги он отдал вперёд, чего за ним раньше не водилось, и руки у него тряслись, пока он их отсчитывал. Ты с ним поласковей, мы с ним в детстве вместе воровали яблоки. Возьми средний замок и новые винты, старые ты опять потерял, растяпа.","chain":"hobart_locks","part":2},{"id":"cellar_013","kind":"note","title":"Очередь к колодцу","text":"Очередь к колодцу для тех, кто опять забыл. В понедельник воду берут Тэннеры, во вторник Холлы, в среду снова Тэннеры, раз уж Холлы вечно забывают про свой день. В четверг идут Рэдли. В пятницу никто не ходит, потому что ведро по пятницам поднимается тяжелее, чем опускали, и мы все это видели. В субботу берут Холлы, и пусть наконец принесут свою верёвку. Марта Холл, это про тебя, я всё помню."},{"id":"cellar_014","kind":"note","title":"Любовная записка","text":"Эдвин, матушка уезжает в среду на весь день. Принеси, пожалуйста, того сыра, что мы ели на ярмарке. Это я всерьёз, сыр мне очень понравился. Можешь и сам прийти. Я уже три дня только об этом и думаю, о сыре, разумеется."},{"id":"cellar_015","kind":"note","title":"Записанная шутка","text":"Записываю шутку мельника, чтобы рассказать на празднике. Приходит сборщик податей к вдове и спрашивает, что у неё есть в подвале. Она отвечает: паутина. Он спрашивает, сколько. Она говорит: забирайте всю. Когда рассказывал мельник, мы с сёстрами смеялись до слёз, а теперь я записала и вижу, что вышло неверно. Там ещё был осёл. Придётся зайти к мельнику и спросить, а мне только того и надо."},{"id":"cellar_016","kind":"note","title":"Записка Гарольду","text":"Гарольд, сердце моё, не сердись. Я продала твои старые сапоги, потому что они текли, и на эти деньги взяла тебе новые, получше. Новые оказались малы, и я их тоже продала, правда, дешевле. Суп стоит на печи, ешь, пока горячий. Я вернусь от сестры к вечеру, и мы вместе подумаем, в чём тебе завтра идти на работу. Твоя Бетси, которая тебя любит и надеется на то же самое."},{"id":"cellar_017","kind":"note","title":"Приказ цеха","text":"Цех свечников приказывает больше не хранить воск под амбаром Дарби. Свечи третьей партии горят как положено, только пламя у них клонится к полу, хотя сквозняка там нет. Партию продайте в соседний приход, они там ни на что не жалуются. Подмастерье Гектор пусть воск не пробует, ему это говорили уже дважды. Гектор, это я пишу тебе лично: твоя мать просила за тобой приглядывать, а ты мне очень усложняешь дело."},{"id":"cellar_018","kind":"note","title":"Записка в щели","text":"Милая соседка, вашим вторым яйцом наелись все пятеро и ещё оставили на завтра. Сегодня я нашла в щели третье, побольше, и оно было тёплое. Щель за эту неделю стала шире, иначе как бы оно пролезло, зато теперь я могу передать вам пирог с луком и шарф, у вас там наверняка зябко. Шарф старый, не обижайтесь, его вязала ещё моя мать. Мне приятно, что у меня есть вы. Гвен.","chain":"salt_loan","part":3},{"id":"cellar_019","kind":"note","title":"Из дневника","text":"Сегодня мне исполнилось тринадцать, и тётя подарила мне напёрсток. На рынке Джон Арден смотрел на меня, а может быть, на морковь у меня за спиной. Я потом нарочно ходила проверить, и морковь там правда лежала. Но я всё равно решила, что смотрел он на меня, а морковь пускай думает что хочет."},{"id":"cellar_020","kind":"note","title":"Просьба соседям","text":"Соседи, кто взял лестницу со двора Пайков, верните её, пожалуйста. Погреб у нас без ступеней, и наш сын сидит там уже второй день. Хлеб мы спускаем ему на бечёвке, а самого его на ней не вытащишь, парень он крупный. Он кричит снизу, что можно не спешить, потому что там тихо и никто не заставляет колоть дрова. Мать извелась, а отец говорит, что давно не слышал от него столько слов подряд. Марта Пайк."},{"id":"cellar_021","kind":"note","title":"Договор","text":"Мы, Стэнли Рот и тёща его Берта, договорились при свидетеле о следующем. Она больше не заходит в мастерскую, а он не поёт за столом. Оба признают, что друг друга не выносят, и оба обещают не огорчать Молли, которую любят одну на двоих. Свидетель просит в другой раз его не звать, он ещё от прошлого договора не отошёл."},{"id":"cellar_022","kind":"note","title":"Наряд подмастерью","text":"Перси, поставь Хобарту третий замок, у самого порога, ниже ставить уже некуда, так ему и скажи. Дверь открывать он не велел, поэтому работай с этой стороны. Если изнутри тебя попросят подать инструмент, не подавай и не отвечай, кто бы ни просил, хоть бы и голосом его жены. Я за тебя боюсь, мальчик. Клещи у нас одни, и ты у меня тоже один.","chain":"hobart_locks","part":3},{"id":"cellar_023","kind":"note","title":"Книга повитухи","text":"Роды у Мэгги Дин прошли за четыре часа с небольшим, мальчик родился здоровый, и я, как всегда, расплакалась. Плату взяла курицей. Мэгги просит записать, что, пока она кричала, в подвале кто-то пел колыбельную. Я спускалась туда с лампой и никого не нашла. Записала, как она просила, за сорок лет я научилась не спорить с роженицами. Курица несётся плохо."},{"id":"cellar_024","kind":"note","title":"Записка у порога","text":"Госпожа Ив, я оставляю пирог у двери, вы уже неделю мне не открываете. Прошлый противень я забрала, он был вылизан дочиста, хотя раньше вы всегда оставляли корки. Вы здоровы? Утром я стучала и слышала, как кто-то отходит от двери на цыпочках, и отходил он очень долго, а у вас ведь всего одна комната. Откройте мне, пожалуйста. Мы с вами тридцать лет ругаемся через забор, и я ещё не закончила."},{"id":"cellar_025","kind":"note","title":"Перепись двора","text":"В доме Хоука живут муж, жена, трое детей, тёща и козёл, причём тёща просит записать козла последним. В доме Броков живут муж, жена и двое детей. Броки говорят, что в подвале у них живёт ещё один, а кем он им приходится, сказать не могут. Хозяйка каждый вечер ставит ему у люка тарелку, и утром тарелка пустая. Подать за него я брать не стал. Кто ест и никому не мешает, тот, по-моему, уже родственник."},{"id":"cellar_026","kind":"note","title":"Табличка на лестнице","text":"Детям спускаться только со взрослыми. Взрослым только вдвоём. Вдвоём только днём. Днём у нас работа, так что сидите наверху, дорогие мои, мне так спокойнее. Ваша бабушка."},{"id":"cellar_027","kind":"note","title":"Долговая книга","text":"Уилкинс должен мне три монеты. Вдова Нэш должна одну, и я её об этом не спрашиваю. Мельник должен шесть, с него надо спрашивать дважды. Кузен Арчи взял одиннадцать и уехал. Кузен Арчи вернулся и занял ещё четыре. Это я сам себе пишу: больше ему не давать. Правда, родни у меня, кроме него, не осталось, и обнимает он всегда так, что я сам лезу за кошельком."},{"id":"cellar_028","kind":"note","title":"Рекомендация","text":"Дорис Кин служила у нас четыре года, и мы расстаёмся с ней со слезами. Она честна, встаёт рано и хорошо управляется с бельём, а наш младший при ней перестал бояться темноты. За всё это время она ни разу не спустилась в подвал, и за это мы ей особенно признательны. Отпускаем её с жалованьем за месяц и просим новых хозяев её беречь. Госпожа Уайт."},{"id":"cellar_029","kind":"note","title":"Записка в щели","text":"Пирог вы взяли, а шарф вернули вдвое длиннее. Вяжете вы ровнее моей матери, и нитка у вас серая, хорошая, только немного липнет к пальцам. Простите моего мужа, он всё-таки замазал щель глиной и всю неделю ходит сам не свой. Мне вас не хватает, правда. Сегодня утром у нас на столе лежало ещё одно яйцо, хотя щели больше нет, и дети просят яичницу. Записку кладу у стены наудачу. Гвен.","chain":"salt_loan","part":4},{"id":"cellar_030","kind":"note","title":"Список приданого","text":"Приданое Энни Брук, записываю сам, чтобы сватья потом не говорила лишнего. Даём две простыни, одна с дырой, зато вышитая. Даём четыре ложки и бабушкин стул, за который Энни держалась, когда училась ходить. Корова остаётся у нас, про корову разговора не было. А дочь мы отдаём самую лучшую, и пусть ваш сын это запомнит."},{"id":"cellar_031","kind":"note","title":"Каракули","text":"ханна дура. сказала что паук был с тарелку. а я видел он был с таз. ханна его вобще не видела потому что зажмурилась она трусиха. я видел и не убежал. потом убежал. но ханну я сначала утащил за руку так что пускай спасибо скажет"},{"id":"cellar_032","kind":"note","title":"Совет хозяйке","text":"Милая Сара, ты теперь хозяйка в своём доме, так что вот тебе мой совет. Пауков не гони, бери стаканом, подсунь снизу лист бумаги, вынеси во двор и скажи спасибо. Твоя бабка их не терпела, и мухи у неё ели хлеб прямо со стола. Последнего паука из подвала я выносила сама, двумя руками, и спасибо сказала два раза. Приезжай к нам на праздник, я по тебе скучаю. Мама."},{"id":"cellar_033","kind":"note","title":"Накладная","text":"Госпоже Ройс доставлены бочонок масла, два куля муки и ящик свечей. Я сгрузил всё у люка, как она велела, а сама она ко мне так и не вышла. Накладную я спустил в люк на верёвочке, и она вернулась с подписью: восемь крестиков по кругу. Раньше госпожа Ройс всегда выносила мне молока и спрашивала про мою Эмму. Я, возчик Дэйл, за такую подпись не отвечаю и ездить туда больше не стану, хотя мне её жаль."},{"id":"cellar_034","kind":"note","title":"Наряд подмастерью","text":"Перси, я сам ходил к Хобарту. Все три замка лежат на верхней ступеньке, снятые чисто, и винты сложены в плошку. Такой работы я от тебя шесть лет жду. Дома никого нет, дверь стоит настежь. Я позвал его, как звал в детстве, и никто мне не откликнулся. Счёт отнеси его сестре на Рыбную, только денег с неё не требуй. Скажи, что я зайду сам и посижу с ней.","chain":"hobart_locks","part":4},{"id":"cellar_035","kind":"note","title":"Записка деду","text":"Дедушка, ты уже поел, не ищи. Суп стоит в печи, это на завтра. Ты опять спрашивал про бабушку: она умерла весной, мой хороший, я знаю, как больно тебе это слышать каждый раз. В подвале её нет, не ходи туда её звать, пожалуйста. Твои очки висят на гвозде у окна. Я вернусь к обеду, посижу с тобой, и мы вспомним, как она ругала тебя за сапоги. Твоя Кейт."},{"id":"cellar_036","kind":"note","title":"Записка на столе","text":"Нэнси, я пошла вниз за углём. Если не вернусь к ужину, сними суп с огня и покорми собаку. За мной без надобности не ходи, а если всё-таки пойдёшь, лишнего угля не бери, он в этом году дорогой. Я, конечно, вернусь. Твой отец за двадцать шесть лет так и не сумел от меня отделаться."},{"id":"cellar_037","kind":"note","title":"Решение совета","text":"Совет постановил считать подвалы под Старой и Мельничной улицами общими, пока не выяснится, кто их копал. Никто из домовладельцев копать не сознался, а записей об этом нет. Подать за подвалы совет будет брать равными долями с первого числа. Господин Дэвис просит внести в протокол, что подвала у него нет и никогда не было. Совет вынужден сообщить господину Дэвису, что подвал у него есть, и советует посмотреть под кухней."},{"id":"cellar_038","kind":"note","title":"Дела на неделю","text":"Починить корыто. Поговорить с Маргарет. Наточить косу. Корыто я починил. Заодно вставил раму на кухне, хотя её в списке не было. Поговорить с Маргарет. Косу наточил. Прибил полку, о которой она просила ещё в прошлом году. Поговорить с Маргарет. Сказать ей, что я был неправ. Поговорить с Маргарет."},{"id":"cellar_039","kind":"note","title":"Записи хозяйки","text":"Масло в погребе опять потекло. Двадцать лет оно у меня держалось до самой жары, а с этой осени внизу тепло, как в хлеву. Я перенесла масло в сени. Потом положила ладонь на пол, и пол был тёплый, будто под ним кто-то лежит и дышит. Молоко я тоже перенесла. Матери про это писать не буду, она и так за меня плохо спит."},{"id":"cellar_040","kind":"note","title":"Молитва","text":"Святой Бертрам, хранитель кладовых, пошли мне мужа, который закрывает за собой дверь. Если такого не осталось, пошли хоть дверь, что закрывается сама. И пусть в этом году не прокиснет молоко. Мой нынешний дверь не закрывает, зато обнимает меня перед сном, так что ты на него не сердись, это я просто ворчу. Аминь."},{"id":"cellar_041","kind":"secret","title":"Записка в кирпиче","text":"Сынок, вчера я выбил кирпич из стены подвала, а на обороте нацарапано: кто будет строить дальше, оставь тут окно. Окна, как видишь, никто не оставил. Я приписал ниже то же самое и вставил кирпич на место. Раствор у нас хороший, ты его не тронешь. Но когда придёт твой черёд класть стены, вспомни отца и оставь окно. Кому-то внизу будет приятно."},{"id":"cellar_042","kind":"secret","title":"Письмо жильцам","text":"Тем, кто построит над нами. Подвал у нас сухой, если не трогать дальний угол. Тяга в печи хорошая. Соседи справа шумные, но вас это уже не коснётся. Ключ от погреба лежит под третьей ступенькой. Мы нашли такой же ключ, когда строились, и такое же письмо, и в первую ночь оно нас очень утешило. Живите тут хорошо, не ссорьтесь из-за пустяков и напишите следующим. Джон и Анна."},{"id":"cellar_043","kind":"secret","title":"Записка сапожника","text":"Записываю, чтобы внуки мне поверили. Старик, который смотрит за огнём на площади, принёс мне чинить башмак и сказал, что дед мой тоже плохо завязывал шнурки и всегда снашивал левый первым. Старику с виду лет шестьдесят, а дед умер, когда площадь ещё не мостили. Левый он и правда снашивал, мне мать рассказывала. Я так обрадовался, что кто-то ещё помнит деда, что взял со старика полцены."},{"id":"cellar_044","kind":"secret","title":"Наказ матери","text":"Дочка, моя мать велела мне, если придёт беда, взять из костра на площади уголёк и нести наверх. Куда наверх, она не сказала, потому что сама не знала, ей так велела её мать. Я пишу это, чтобы ты понимала, зачем за ларём стоит горшок. Уголь в нём я меняю раз в неделю, идти до площади недалеко. Когда меня не станет, меняй его ты и не смейся над старухами. Мы боялись за вас."},{"id":"cellar_045","kind":"secret","title":"Правила обмена","text":"Кто берёт из этой ниши вещь, тот кладёт свою. Я взял гребень и положил свисток. Я взял свисток и положил нож. Я взял нож и положил напёрсток. А я взяла напёрсток, и положить мне нечего, поэтому оставляю эту записку. Простите меня, добрые люди, я шью дочке свадебное платье, а свой напёрсток потеряла."},{"id":"cellar_046","kind":"secret","title":"Мой клад","text":"это мой клад. тут синие стекло. зуб мой. зуб не мой я его нашёл. перо. кто возмёт тому будет плохо. если это ханна то ей будет хуже всех. ханна если это ты то перо можешь взять ты его хотела"},{"id":"cellar_047","kind":"secret","title":"Тайная запись","text":"Я вышла за Джорджа из-за крыши, потому что кто-то должен был её чинить. С тех пор прошло девять лет. Крыша давно целая, а он каждую весну лезет её проверять и зовёт меня держать лестницу. Я хожу и держу. Ему я этого никогда не скажу, но если он однажды перестанет звать, я сама проломлю в ней дыру."},{"id":"cellar_048","kind":"secret","title":"Запись плотника","text":"Мы углубляли погреб на два локтя и пробили чужой потолок. Внизу оказалась кухня, стол там накрыт на двоих, и ложки рыжие от ржавчины. Жена спустилась и вытерла со стола пыль, сказала, что так приличнее, вдруг они вернутся. Я хотел ей что-то ответить и не смог. Доски мы положили обратно, а погреб оставили как был, вина у нас немного."},{"id":"cellar_049","kind":"secret","title":"Считалка","text":"Записала, что поют дети у колодца, когда прыгают через верёвку: «Дом на доме, дом на доме, пятый спит, шестой в соломе. Кто внизу, тот подождёт, кто вверху, тот упадёт». Я спросила у старой Бесси, откуда это, и она сказала, что пели всегда, ей пела мать, а матери бабка. Что это за дома, никто не знает. А я теперь не могу спокойно слушать, пока моя младшая прыгает там со всеми."},{"id":"cellar_050","kind":"secret","title":"Страница дневника","text":"Староста вывесил объявление: нужен кто-нибудь, кто согласен спуститься, плата хорошая. Пошёл мой Адриан с мельницы. Он вернулся через неделю, худой, и всё говорил про какие-то улицы внизу. Платить ему отказались, потому что договаривались только про спуск. Я варю ему бульон, а он сидит и смотрит в пол. Вчера вывесили новое такое же объявление, и плату подняли на монету. Он уже ходил его читать, и я спрятала его сапоги."},{"id":"cellar_051","kind":"boss","title":"Письмо дочери","text":"Мама, я пишу на обороте счёта, другой бумаги нет. Ты опять приходила ночью и укрывала нас. Ноги у тебя теперь так тихо стучат по балкам, что младший думает, это дождь. Он спрашивает, когда мы выйдем. Я говорю, когда ты закончишь плести одеяло.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_052","kind":"boss","title":"Жалоба соседке","text":"Уважаемая соседка! Ваше одеяло снова приползло к нам через отдушину, дошло до полки с вареньем и обвило её. Я его обрезала, а к утру оно срослось. Работа прекрасная, слов нет, и я помню, как вы сидели с моей Хильдой, когда она болела. Но у нас своего места мало, а у вас столько детей. Заберите его, пожалуйста, или скажите, сколько его ещё будет. И зайдите ко мне, я давно вас не видела.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_053","kind":"boss","title":"Счёт за шерсть","text":"Лавка Хемминга, счёт матери с Прядильного двора. За серую шерсть, двенадцать мотков. За серую шерсть, сорок мотков. За шерсть, сколько её у меня было. За осень вы не заплатили, и я не прошу, дорогая, я ведь знаю, сколько у вас ртов. Только заказов от вас больше не приходит. Вторую половину этого счёта забрала ваша девочка, сказала, что ей нужна бумага. Она очень худая, я дала ей хлеба.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_054","kind":"boss","title":"Записи сетчика","text":"Я чиню сети тридцать лет. Вчера соседка, мать восьмерых, принесла мне на пробу нитку. Узел на ней не нужен, нить сама липнет к нити, а нож об неё тупится. Я спросил, где она берёт такую шерсть. Она сказала, что своя, и спрятала руки под передник. Мы знакомы с детства, и раньше она ничего от меня не прятала. Заказал у неё сорок локтей для лодки Харпера, цена хорошая, и детям её будет на хлеб.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_055","kind":"boss","title":"Записка младшего","text":"роб велел писать каждый день чтобы я не разучился и написать что я не боюсь. я не боюсь. мама принесла нам поесть завёрнутое в одеяло. это можно есть только я не знаю что это. лотти говорит не спрашывай. дождь опять ходит по балкам. я знаю что это мама. лотти думает я не знаю а я не говорю чтобы она не плакала","boss":"boss_spider","floors":[1,2]},{"id":"cellar_056","kind":"boss","title":"Правила дома","text":"Пишу я, Роб, потому что я теперь старший. Одеяло не поднимайте. Если стучит наверху, это мама. Если стучит внизу, будите меня. Про её ноги при ней не говорите, она от этого расстраивается. Воду сегодня делит Лотти, завтра Дэви, и младшему всегда давайте первому. При ней не ссоримся и не плачем. Она нас кормит и укрывает, и она всё ещё наша мама.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_057","kind":"boss","title":"Письмо сестре","text":"Дорогая Эвелин, ты спрашивала про ту многодетную с нашего двора. Детей её давно никто не видит, и я за них тревожусь. На той неделе мой Джем уснул раскрытым, окно было открыто, а утром он лежал укрытый по самую шею, и укрыт чем-то серым, ровным, у нас такого сроду не водилось. Муж говорит, что это не он. Я сперва испугалась, а потом потрогала: одеяло тёплое. Мы его оставили. Кто-то же пожалел моего мальчика.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_058","kind":"boss","title":"Письмо брата","text":"Лотти, сестрёнка, я устроился у шорника в Нижнем Форде, и тут кормят. Шлю три монеты, отдай их маме и скажи, что одеяло дошло. Оно мне велико, им можно укрыть лошадь. Я мерил его осенью и мерил вчера, и оно выросло на локоть. Всё думаю, как мама плела его ночами и не давала мне посмотреть. Почему вы не пишете? Напиши мне хоть строчку, мне без вас плохо. Твой брат Уолтер.","boss":"boss_spider","floors":[1,2]},{"id":"crypt_001","kind":"note","title":"Прейскурант","text":"Обычную могилу в шесть футов мы копаем за три монеты, а каждый фут глубже стоит ещё монету. Мельче копать не станем, и не просите. За каменистый грунт я беру особо, потому что спина у меня одна. Если покойника придётся закапывать второй раз, платит родня. Вдовам и вдовцам я копаю за две монеты: так завёл мой отец в тот год, когда похоронил мою мать. Гарольд, могильщик."},{"id":"crypt_002","kind":"note","title":"Поминки","text":"Лотти, на поминки по тётушке Дагмар придут тридцать человек, так что зажарь два окорока и закажи бочонок пива, а яблочный пирог я испеку сама. Сыра много не бери, она его никогда не ела. И отодвинь её стул от окна. В прошлом году она пришла на собственные поминки, села на сквозняке и весь вечер ворчала, что ей продуло спину. Я так по ней соскучилась, что поддакивала."},{"id":"crypt_003","kind":"note","title":"Детской рукой","text":"мама велела написать как всё было. мы с бенни играли в прятки на кладбище. я спрятался за ангелом и меня долго никто не нашол и стало темно и я заплакал. потом пришла какая то тётя и сказала что бенни уже дома и отвела меня к воротам. у неё в волосах была земля. она назвала меня воробушком. я сказал спасибо. мама говорит так меня звала только бабушка но я её не помню. утром мама пошла к бабушке на могилу и взяла с собой гребешок"},{"id":"crypt_004","kind":"note","title":"Жалоба смотрителю","text":"Господин смотритель, камень на границе нашего участка и участка Тредуэллов передвинули на ладонь в мою сторону. Мой покойный свёкор всегда лежал ровно посередине своего места, а теперь у него нога оказалась на чужой земле. Этот старик был ко мне добрее родного отца, и я не позволю ему лежать на земле Тредуэллов. Прошу вас вернуть камень и взыскать с виновного. Агнес Марлоу.","chain":"crypt_boundary","part":1},{"id":"crypt_005","kind":"note","title":"Табличка на воротах","text":"Дорогие родные, очень прошу вас не ставить еду на могилы. От неё заводятся крысы, а утром кто-нибудь непременно видит пустую тарелку, и по всему городу идут разговоры. Я понимаю, что вы хотите порадовать своих. Если душа просит, принесите пирог мне в сторожку, я съем его за вашего покойного и с удовольствием послушаю, каким он был человеком. Смотритель."},{"id":"crypt_006","kind":"note","title":"Квитанция","text":"Вдове Блэр. Я получил от вас четыре монеты за дубовый гроб. В пятницу ваш Томас встал, принёс гроб ко мне на спине и сказал, что в плечах тесновато. Крышка цела, состояние хорошее, поэтому три монеты я возвращаю. Одну оставляю себе за беспокойство: тридцать лет я делаю гробы, и на мою работу ещё никто не жаловался лично. Кланяйтесь ему, мы с ним всё-таки вместе росли. Гробовщик Оукс."},{"id":"crypt_007","kind":"note","title":"Заказ резчику","text":"Мастер Корвин, вы знали моего Эдмунда, так что поймёте меня. Прошу вырезать на камне: «Любимому мужу, Эдмунду Холлу, лучшему из людей». Буквы сделайте глубокие, с золотом по краю, чтобы их можно было прочесть и через сто лет. Двадцать шесть зим он грел мне ноги и ни разу не сказал, что они холодные. Задаток я оставила у вашей жены. Вдова Пруденс Холл.","chain":"crypt_epitaph","part":1},{"id":"crypt_008","kind":"note","title":"Циркуляр цеха","text":"Цех гробовщиков, всем мастерам. Братья, с первого числа заколачивайте крышки девятью гвоздями вместо шести. Разницу берите с заказчика и объясняйте, что подорожало железо. Настоящую причину родне не называйте: шести гвоздей покойнику теперь хватает только до среды. Людям и так тяжело, незачем им об этом знать. Берегите руки и спите, пока спится. Старшина цеха."},{"id":"crypt_009","kind":"note","title":"Письмо сестре","text":"Энни, ты же знаешь, что сорок лет я плачу на чужих похоронах за деньги. Когда хоронили моего Уилла, у меня не вышло ни слезинки, и соседки всё это видели. Дома я села и подсчитала, сколько взяла бы за такие похороны. Вышло шесть монет. Утром я пошла к Фитцам, у них умер свёкор, и ревела там так, что хозяйка прибавила мне монету. Она думала, что я плачу по свёкру. Приезжай, сестрёнка, мне очень плохо одной."},{"id":"crypt_010","kind":"note","title":"Письмо жене","text":"Дорогая Марта, устроился я хорошо. Здесь сыровато, зато сосед тихий, бывший аптекарь. Пришли мне, пожалуйста, шерстяные носки, синие, а то ноги мёрзнут. Письмо я оставлю под камнем, ты найдёшь его, когда придёшь поливать астры. Скажи Бобу, чтобы не бросал калитку открытой. Не плачь, голубка, и ешь как следует, я же знаю, что одна ты совсем перестанешь готовить. Твой Годфри.","chain":"crypt_letters","part":1},{"id":"crypt_011","kind":"note","title":"Наказ ученику","text":"Том, прежде чем рубить, всегда переворачивай плиту. Камень у нас старый, и на обороте часто стоит чьё-то имя. Чужое имя замажь раствором и работай спокойно. Но если на обороте окажется то самое имя, которое сейчас заказали, и тот же год, ничего не руби, сразу позови меня и родне ни слова не говори. Со мной такое было дважды, и оба раза я потом не спал. И надень рукавицы, я тебя прошу: без пальцев ты мне в мастерской не нужен, а я к тебе уже привык."},{"id":"crypt_012","kind":"note","title":"Эпитафия","text":"Здесь лежит Нед Уик, который до последнего дня говорил, что кашель у него пустяковый. Я тебе говорила, Нед. Приду в воскресенье и скажу ещё раз. Твоя Бетси."},{"id":"crypt_013","kind":"note","title":"Надпись на камне","text":"Наша Пиппа Роу прожила два года и четыре месяца и больше всего на свете любила пуговицы. Если вы найдёте пуговицу, положите её сюда, пожалуйста. Мы с отцом всё ещё находим их по всему дому и приносим ей."},{"id":"crypt_014","kind":"note","title":"Ответ соседке","text":"Госпожа Марлоу, камень стоял так ещё при моём отце, и отец мой считать умел. Ваш свёкор при жизни занимал чужое место и на рынке, и у колодца. Если теперь у него нога оказалась на моей земле, то это у вас семейное. Камня я не трону. Мы с вами тридцать лет не здороваемся, и я не вижу причин начинать, но ваши астры в этом году удались, это я признаю. Бартоломью Тредуэлл.","chain":"crypt_boundary","part":2},{"id":"crypt_015","kind":"note","title":"График дежурств","text":"В понедельник дежурит Рид. Во вторник Рида хоронят, поэтому вместо него выйдет Оуэн. В среду дежурит Оуэн. В четверг Рид вышел на работу сам, и я, братцы, чуть не расплакался, так я ему обрадовался. В пятницу дежурит Рид. За вторник жалованье Риду не начислять, потому что он отсутствовал. Не обижайся, Рид, порядок есть порядок, а пива я тебе поставлю, если ты теперь пьёшь."},{"id":"crypt_016","kind":"note","title":"Прошение","text":"Господин смотритель, прошу вас перенести мою бабушку Гертруду на южную сторону, потому что на северной у неё ноет колено. О колене она сообщила нам сама, в четверг, за ужином. Мы её очень любим и рады видеть, но она сидит у нас уже четвёртый вечер и говорит, что ляжет обратно только на солнышке. Ваш покорный слуга Джозеф Пайк, её внук."},{"id":"crypt_017","kind":"note","title":"Счёт таверны","text":"Стол могильщиков. Гарольд выпил шесть кружек, Симон четыре. Тот, что сидел с ними, взял одну и не притронулся к ней, только держал её в руках и слушал, как они смеются. Ушёл он, не заплатив. Запишу его кружку на Гарольда, потому что Гарольд его закапывал. Гарольд не спорил и велел в следующий раз налить ему того же, что и всегда."},{"id":"crypt_018","kind":"note","title":"Второе письмо","text":"Мастер Корвин, уберите, пожалуйста, «лучшему из людей». Я разбираю стол Эдмунда и реву над каждым ящиком, а сегодня нашла в нём счета от некой Розалинды за ленты. Никаких лент я от него за двадцать шесть лет не видела! «Любимому» пока оставьте, я ещё не всё разобрала. Пруденс Холл.","chain":"crypt_epitaph","part":2},{"id":"crypt_019","kind":"note","title":"Рецепт","text":"Мама оставила мне рецепт пирога на поминки: яблоки, мёд, корица и муки сколько возьмёт. Сколько возьмёт, мама? Я пекла уже три раза, и каждый раз выходит камень. Говорят, хранитель книги поднимает покойных, чтобы уточнить у них то, что не записано, и я думаю об этом чаще, чем хотелось бы. Я спросила бы только про муку, честное слово, а потом ещё немножко посидела бы с тобой."},{"id":"crypt_020","kind":"note","title":"Школьная задача","text":"В ряду двенадцать могил. Ночью из них вышли трое, а к утру вернулись двое. Сколько могил должен проверить смотритель? Ответ Лиама: все двенадцать, потому что папа всегда проверяет все, а потом долго моет руки. Рукой учителя: верно, Лиам, но запиши ход решения. И передай папе, чтобы он не ходил туда один, мы все за него волнуемся."},{"id":"crypt_021","kind":"note","title":"Второе письмо","text":"Марта, носки я получил, спасибо, только левый маловат. По вечерам больше не приходи: ты сидишь на сырой траве, а спина у тебя сама знаешь какая. Аптекарь советует барсучий жир, натирай на ночь и не жалей. Приходи лучше днём, когда сухо, и садись на скамейку, я для того её и просил поставить. Мне оттуда всё слышно, голубка. Твой Г.","chain":"crypt_letters","part":2},{"id":"crypt_022","kind":"note","title":"Молитва","text":"Пошли нам, Господи, сухую землю и нетяжёлую глину. Сделай так, чтобы лопата опять не упёрлась в черепицу, а то этой осенью такое случилось уже в третий раз, и все мы делаем вид, что это камень. И дай моей Мэри поправиться. Про землю я прошу для порядка, а про неё всерьёз. Записываю это, потому что вслух при ней сказать не могу."},{"id":"crypt_023","kind":"note","title":"Любовная записка","text":"Кларисса, я буду ждать тебя у склепа Вейнов после вечерни, туда никто не ходит. Надень ту голубую ленту, я всю неделю о ней думаю. Я знаю, что ты жена смотрителя, и знаю, что нам надо это прекратить, но третью ночь не сплю. Покойники никому не скажут. Вейны, правда, могут, но они со всеми в ссоре, и их никто не станет слушать. Твой до гроба, а здесь до него недалеко."},{"id":"crypt_024","kind":"note","title":"Записка на могиле","text":"Ада, я положил с тобой гребень, как ты просила. Потом я вспомнил, что волосы ты всегда расчёсывала левой рукой, а гребень я вложил тебе в правую. Ночью я сходил и переложил его. Смотрителю я сказал, что это был крот. Пятьдесят лет ты меня поправляла, милая, а теперь приходится самому."},{"id":"crypt_025","kind":"note","title":"Запись смотрителя","text":"Участки Марлоу и Тредуэлл я измерил шагами дважды, и оба раза вышло по-разному. Камень я поставил посередине и велел родне успокоиться. Утром он снова оказался на стороне Марлоу, а земля была взрыта с обеих сторон. На следующую ночь я запер обоих спорщиков у себя в сторожке, и до утра они ругались у меня на глазах, а камень всё равно сдвинулся. Жена спрашивает, кто же его двигает. Я велел ей ложиться и запер дверь.","chain":"crypt_boundary","part":3},{"id":"crypt_026","kind":"note","title":"Объявление","text":"Я потерял вставную челюсть, деревянную, на похоронах моего друга Хиггинса. Нашедшему дам вознаграждение. Если её нашёл сам Хиггинс, пусть оставит себе, я обзавёлся новой. Мы с ним сорок лет делили одну скамейку и один табак, так что поделим и это."},{"id":"crypt_027","kind":"note","title":"Дневник","text":"Я зарыл Буна у ограды, где нельзя, и никому не показал это место. Четырнадцать лет он спал у меня в ногах. Через неделю ночью кто-то стал копать у меня во дворе, я вышел с палкой и не сразу понял, кто это. Потом я сел прямо на землю и заплакал. Принёс ему кость, он её не взял, зато махал хвостом. Теперь я оставляю дверь открытой."},{"id":"crypt_028","kind":"note","title":"Третье письмо","text":"Мастер Корвин, «любимому» оставьте и больше не трогайте. Розалинда оказалась шляпницей. Ленты он брал на шляпу для меня, шляпа оплачена и три года ждала у неё на полке, потому что этот человек три года забывал её забрать. «Лучшему из людей» не возвращайте, раз он три года забывал. Допишите вместо этого: «Шляпу я забрала». Я сижу в ней на кухне и не знаю, как ещё на него сердиться.","chain":"crypt_epitaph","part":3},{"id":"crypt_029","kind":"note","title":"Правила для новых","text":"Держите лопату при себе. После заката спиной к рядам не стойте. Если кто-то окликнет вас по имени, сначала подумайте, кому вы его называли. Обедаем в сторожке. Кружку мойте за собой, вчера опять оставили. Я вам не мать, ребята, но вашим матерям я обещал, что вы вернётесь домой, так что будьте любезны."},{"id":"crypt_030","kind":"note","title":"Черновик речи","text":"Речь над Альбертом. Друзья! Альберт был честен (зачёркнуто). Альберт был трезв по воскресеньям (зачёркнуто). Альберт был с нами очень долго. Так и оставлю. Он занял у меня двадцать монет и вернул одну, а я до сих пор не знаю, с кем теперь буду ходить на рыбалку."},{"id":"crypt_031","kind":"note","title":"Письмо брату","text":"Хью, отец снова дома. Он вошёл ночью, снял сапоги у двери, как при жизни, и сел на своё место. Мать поставила ему тарелку. Есть он не ест, зато починил забор и, наверное, поможет нам с яблоками. Смотрителю пока ничего не пиши, дождёмся конца сбора. Мать впервые с зимы напевает у печки. Приезжай, брат, сам всё увидишь, только разуйся у двери, он на это смотрит."},{"id":"crypt_032","kind":"note","title":"Письмо мужу","text":"Годфри, преподобный Лоуэлл прочитал твоё письмо и велел его сжечь. Он говорит, что писать ты не можешь, потому что я сама тебя хоронила. Я ответила ему, что левый носок ты ругал всю жизнь, и никто другой этого знать не может. Я вяжу новый, побольше. Письмо я не сожгла, оно лежит у меня под подушкой. Твоя Марта.","chain":"crypt_letters","part":3},{"id":"crypt_033","kind":"note","title":"Обрывок тетради","text":"мама сказала что дедушка теперь спит на горке. а он вчира стоял у забора и смотрел как мы играим. я ему помахала. он не махнул обратно. наверно забыл как. мама не велела ходить к забору но я всё равно пойду потомучто он там один. я возьму его за руку и покажу как надо махать"},{"id":"crypt_034","kind":"note","title":"Шутка","text":"Записываю шутку, которую рассказал сегодня в сторожке, пока не забыл. Приходит покойник к смотрителю и говорит: у меня жалоба. Смотритель отвечает: оставьте в ящике. А покойник ему: так я в ящике и лежу. Вечером я рассказал её жене. Жена не смеялась и сказала, что эту шутку я рассказывал ещё на нашей свадьбе. Вот и хорошо, значит, она помнит нашу свадьбу."},{"id":"crypt_035","kind":"note","title":"Записка жене","text":"Мэг, я сегодня буду поздно. Мы роем могилу сразу на троих, земля сырая, и край уже один раз обвалился. Суп оставь на печи и ложись, не жди меня. Если я приду и скажу, что всё хорошо, сначала спроси меня, как зовут нашу козу. Я не шучу, милая: к Оуэнам муж тоже пришёл ночью и сказал, что всё хорошо. Целую тебя и козу."},{"id":"crypt_036","kind":"note","title":"Запись смотрителя","text":"Госпожа Марлоу скончалась в марте, а Тредуэлл ушёл через три недели, хотя здоровье у него было как у быка. Соседки говорят, что ему стало не с кем ругаться. Они лежат через камень, и камень ходит по ночам примерно на ладонь. Разбираться я перестал и теперь записываю только, в какую сторону он пошёл. Вчера он опять сдвинулся к Марлоу. В трактире принимают ставки, и я поставил на неё.","chain":"crypt_boundary","part":4},{"id":"crypt_037","kind":"note","title":"Расписка","text":"Я, Хэмфри Слоун, занял у Джона Бейли шесть монет и отдам к осенней ярмарке. Ниже другой рукой: Хэмфри умер летом. В день ярмарки я нашёл на подоконнике шесть монет, сырых и в земле. Я вымыл их и положил в кошель. Дурак ты, Хэмфри, мы же с тобой с детства дружили, я бы и так простил."},{"id":"crypt_038","kind":"note","title":"Счёт резчика","text":"Вдове Холл. Первая надпись с золотом стоит шесть монет, а её стёсывание две. Вторая надпись стоит три монеты, стёсывание ещё две. Третья надпись тоже три. Камень стал тоньше на палец, но за это я не беру. Шляпа вам к лицу. Моя жена видела вас в ней в церкви и сказала, что Эдмунд, старый растяпа, всё-таки умел выбирать. Мастер Корвин.","chain":"crypt_epitaph","part":4},{"id":"crypt_039","kind":"note","title":"Листовка","text":"Оберег от вставших покойников! Он сделан из олова, освящён и стоит всего полторы монеты. Подумайте о матушке: она у вас одна, и двоюродный дядя, который умер в прошлом году, у вас тоже один, и он прекрасно знает, где она живёт. Если оберег не поможет, мы вернём деньги. Жалобы принимаем только лично от пострадавшего."},{"id":"crypt_040","kind":"note","title":"Последнее письмо","text":"Марта, мне сказали, что ты теперь здесь, в восточном ряду. Я так и знал, что ты опять сидела на сырой траве. Спроси у смотрителя, нельзя ли поменяться местами с Хопкинсами, а то через два ряда кричать неудобно, да и голос у меня уже не тот. Носки можно больше не вязать, теперь отдыхай. Я ждал тебя, голубка, и совсем не торопил. Твой Годфри.","chain":"crypt_letters","part":4},{"id":"crypt_041","kind":"secret","title":"За кирпичом","text":"Дик, ты спрашивал, откуда у нас новая миска. Мы копали под склепом Фарроу и вышли на черепицу. Под черепицей оказалась комната, в комнате стоял стол, а на столе миска. Смотрителю я сказал, что там камень. Миску, если честно, я взял, уж очень она хорошая. Только маме не говори, что до нас из неё кто-то ел суп, лет за тысячу."},{"id":"crypt_042","kind":"secret","title":"Под плитой","text":"В фундаменте часовни я нашёл плиту с именем моего деда. Дед жив и ходит на рынок. Плита старше часовни, и мох на ней старше меня. Я поставил её обратно лицом внутрь. Деду я ничего не сказал: сердце у него слабое, и я люблю этого старого ворчуна, так что пусть ещё походит на рынок."},{"id":"crypt_043","kind":"secret","title":"Детской рукой","text":"тут мои конфеты. кто возьмёт будет проклят. это честное проклятие, я попросила тётю из склепа и она кивнула. но если ты грустный то можно взять одну. тётя тоже сказала ладно"},{"id":"crypt_044","kind":"secret","title":"Между томами","text":"Я перебрал книги усопших за двести лет, всё искал старика, который смотрит за огнём на площади. Нет ни записи о рождении, ни могилы. Тогда я решил спросить у него самого, как его зовут и откуда он взялся. Сел к костру, а он подвинул мне кружку и спросил, как там мой сын. Мы проговорили о сыне до утра, и мне впервые за эти годы стало легче. Как его зовут, я так и не спросил."},{"id":"crypt_045","kind":"secret","title":"В склепе","text":"Кто-то прокопал ход между склепом Линчей и склепом Барроу. Мы думали, что это воры, но ничего не пропало. В ходе стоят две кружки, а колода карт разложена на середине партии. Старики Линч и Барроу пятьдесят лет играли по четвергам, и каждый на смертном одре клялся, что другой жульничал. Закрывать ход я пока не стал, Барроу вроде выигрывает."},{"id":"crypt_046","kind":"secret","title":"Старая надпись","text":"Сестрица, на дне старого склепа мы нашли надпись, и буквы там почти такие же, как наши. Отец Мэтью смог разобрать только конец: «...оставляем вам. Крыша течёт с северной стороны, простите». Крыша там и вправду течёт с северной стороны. Кто-то умер задолго до всех нас и всё равно стыдился перед нами за крышу. Отец Мэтью прослезился, и я, признаться, тоже."},{"id":"crypt_047","kind":"secret","title":"В кувшине","text":"Кто бы ты ни был, милый человек, в этом кувшине лежат семена, а рядом мешочек соли. Я закопала их на случай, если наверху станет худо. Семена прошлогодние, и с тыквами у меня никогда не получалось, так что не обессудь. Дочка смеётся, что я прячу еду для людей, которых нет. А я думаю, что ты будешь. Ешь как следует и одевайся теплее."},{"id":"crypt_048","kind":"secret","title":"Письмо без адреса","text":"На похоронах судьи Уайта я плакала за четыре монеты. Он был мой отец, об этом знали только мы двое, а теперь знаю я одна. Плакала я как обычно, чтобы никто не заметил разницы. Однажды на рынке, когда мне было семь лет, он взял меня за подбородок и сказал, что я похожа на мать. Деньги лежат здесь. Тратить их я не хочу, а выбросить жалко."},{"id":"crypt_049","kind":"secret","title":"Список смотрителя","text":"Пишу для себя, в книгу этого не заношу. Этой осенью выходили и вернулись до рассвета Эбби Кларк, Нил Мур и двое Стэнли. Ходили они только домой и постояли под окнами. Если об этом узнает хранитель книги, он будет поднимать их на допрос, так что пусть постоят. Эбби всю жизнь сама укладывала детей и теперь хочет только послушать, как они засыпают."},{"id":"crypt_050","kind":"secret","title":"За ящиком","text":"Мама, Дэн опять спустился через провал за часовней, и я не смог его удержать. Он говорит, что ниже нашего есть ещё одно кладбище, что на плитах там наши фамилии, только пишутся они странно, а на каждой третьей лежат свежие цветы. Я спросил его, кто их носит. Он пожал плечами и пошёл ужинать. Поговори с ним, тебя он слушает, а у меня сердце не на месте."},{"id":"crypt_051","kind":"boss","title":"Книга усопших","text":"Аделина Корр, прачка. Умерла весной. Поднята для уточнения даты. Дату не помнит. Поднята повторно. Просит прекратить. Причина просьбы не указана, запрос возвращён заявителю.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_052","kind":"boss","title":"Том 88","text":"Эзра Нолл, кровельщик. Графа причины смерти заполнена неразборчиво. Поднят для уточнения. Показал, что упал с крыши. Какая это была крыша, не указано. Поднят повторно, чтобы уточнить крышу. В настоящее время указывает рукой на север и ложиться отказывается. Дело открыто. На полях рукой писца: это крыша его дочери, он чинил её перед зимой и не успел закончить.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_053","kind":"boss","title":"Прошение вдовы","text":"Господин хранитель, пишет вам вдова Тиббс. Моего мужа вы поднимали уже три раза, записи об этом у вас есть, а он совсем исхудал. Я всю жизнь его откармливала, он и так был худой. Прошу вас, оставьте его в покое хотя бы до весны, дайте человеку полежать. Пометка канцелярии: заявитель в книге усопших не значится. Подать повторно после внесения.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_054","kind":"boss","title":"Жалоба совету","text":"Хранитель поднял весь южный ряд для сверки. Третий год они стоят вдоль стены по алфавиту, и к колодцу пройти нельзя. Просим сверять их в другом месте или хотя бы убрать с прохода букву М. Там стоит Том Миллер, муж нашей Лиззи, и она каждое утро приносит ему шарф, а он её не узнаёт. Подписали жители Кладбищенского переулка.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_055","kind":"boss","title":"Жалоба писца","text":"Совету от писца Арно. Я служу при книге двенадцатый год. Господин хранитель требует точности до часа и велел поднимать всех за двести лет подряд. Я попросил у него один день на похороны матери. Он ответил, что мать будет поднята в свой черёд, и тогда я с ней увижусь. Он сказал это ласково, господа, как будто дарил мне что-то. Прошу вас, заберите меня от него.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_056","kind":"boss","title":"Том без номера","text":"Хранитель книги усопших. Имя: смотри том первый. Том первый не найден. Умер, по словам писца, зимой. Поднят собственноручно для уточнения. Дату не помнит. Приступил к обязанностям. Приписка писца: я сам закрыл ему глаза, а утром он сидел за столом и спрашивал, почему чернила стоят не на месте. Я принёс ему чернила. Что мне ещё было делать?","boss":"boss_necro","floors":[3,4]},{"id":"crypt_057","kind":"boss","title":"Детское прошение","text":"господин хранитель. это нелли. вы подняли мою бабушку спросить про дату а она всё говорит про пироги. пожалуста пусть она ещё немножко поговорит. папа сказал что нельзя просить но вы же всё равно её спрашиваете. я могу сама приходить и слушать про пироги а вы идите отдохните, вы наверно устали","boss":"boss_necro","floors":[3,4]},{"id":"crypt_058","kind":"boss","title":"Вырванный лист","text":"Мэрион, жена хранителя. Умерла на исходе зимы, дата известна, уточнений не требуется. Поднята для уточнения, не холодно ли ей. Поднята для уточнения, ела ли она. Поднята для уточнения, сердится ли. Поднята для уточнения. Поднята для уточнения. Продолжение на обороте.","boss":"boss_necro","floors":[3,4]},{"id":"flooded_001","kind":"note","title":"Смена адреса","text":"Почтовой конторе. Прошу вас письма для Долорес Хобб носить теперь на второй этаж, Тростниковая, дом 4, потому что первый этаж на лето заняла река. Стучите громче, я глуховата. Вашему мальчику передайте, что сапоги можно не снимать, полы у меня всё равно мокрые.","chain":"address_change","part":1},{"id":"flooded_002","kind":"note","title":"Смена адреса","text":"Почтовой конторе. Это снова Долорес Хобб. Я перебралась на чердак того же дома, и почтальону придётся подниматься по приставной лестнице. Третья перекладина гнилая, пусть мальчик бережёт ноги, он у вас хороший. Посылку от племянника прошу не мочить, там чай, а племянник у меня один и вспоминает обо мне раз в год.","chain":"address_change","part":2},{"id":"flooded_003","kind":"note","title":"Смена адреса","text":"Почтовой конторе. Долорес Хобб живёт теперь на крыше того же дома, от трубы налево. Я спускаю корзину на верёвке, кидайте письма с лодки прямо в неё. Ваш мальчик бросает плохо, вчерашнее письмо утонуло, и я так и не узнала, родила ли моя внучка Мэг. Я всю ночь не спала. Напишите ей, пожалуйста, чтобы прислала ещё раз, и пусть мальчик в этот раз прицелится.","chain":"address_change","part":3},{"id":"flooded_004","kind":"note","title":"Смена адреса","text":"Почтовой конторе от Долорес Хобб. Больше письма носить не надо, племянник всё-таки вспомнил обо мне и забирает на холм. Мальчику вашему спасибо за старание. Если придёт письмо от Мэг, перешлите его. А если Мэг приедет сама и станет искать дом четыре, скажите ей, что дом стоит на месте, просто теперь пониже, а бабушка ждёт её на холме и уже вяжет крошечные носки.","chain":"address_change","part":4},{"id":"flooded_005","kind":"note","title":"Жалоба","text":"Портовому совету от Гектора Брандта, торговца солью. В моём подвале лежало сорок мешков соли. Теперь там лежат сорок мешков. Соль ушла в реку без разрешения и без оплаты. Прошу взыскать с реки двести монет. Жена велит мне успокоиться. Я спокоен, я просто пишу жалобу.","chain":"salt_claim","part":1},{"id":"flooded_006","kind":"note","title":"Ответ совета","text":"Господину Брандту. Совет вам искренне сочувствует. Иск к реке мы сможем принять, как только вы укажете её постоянное место жительства. На сегодня река проживает в том числе и в здании совета, поэтому заседание откладывается. Вашей супруге совет кланяется и просит её приглядеть за вами.","chain":"salt_claim","part":2},{"id":"flooded_007","kind":"note","title":"Вторая жалоба","text":"Совету от Гектора Брандта. Извольте, вот место жительства реки: Рыбная улица, Кожевенная улица, моя лавка и ваше здание. Прошу также учесть, что сельдь у причала теперь продают уже солёной, без моего согласия. Соль эта моя, и я требую долю с каждой селёдки. Жена сказала, что я смешон. Прошу приобщить к делу, что она эту селёдку тоже ест.","chain":"salt_claim","part":3},{"id":"flooded_008","kind":"note","title":"Объявление","text":"Рассол высшего качества! Отборная вода с Рыбной улицы, настоянная на сорока мешках лучшей соли. Монета за ведро, ведро приносите своё. Черпаю сам, прямо из окна. Г. Брандт и сын. Сын просит добавить, что ему стыдно. Отец просит добавить, что сын ест его хлеб.","chain":"salt_claim","part":4},{"id":"flooded_009","kind":"note","title":"Записка в ведре","text":"Мэйбл, раз улица теперь внизу, я перекинул верёвку от моего окна к твоему. Видишь ведро? Тяни его к себе, в нём пирог. Он с угрём, потому что теперь всё с угрём, но пёк я его сам и всё время думал о тебе, так что ешь и не морщись. Тоби из дома напротив.","chain":"rope_bucket","part":1},{"id":"flooded_010","kind":"note","title":"Записка в ведре","text":"Тоби, пирог мы съели. Отец спрашивает, кто его прислал, и я сказала, что ветром надуло. Верёвка у тебя провисает, ведро черпает воду, и твою последнюю записку я разбирала целый час. Разобрала всю, даже то, что ты зачеркнул, и мне понравилось. Подтяни верёвку со своей стороны, пожалуйста.","chain":"rope_bucket","part":2},{"id":"flooded_011","kind":"note","title":"Записка в ведре","text":"Мэйбл, я подтянул, сколько смог. Узел теперь на чердачном окне, потому что ниже привязывать уже не к чему. Завтра мы с отцом разбираем крышу на плот, так что ты, пожалуйста, не отвязывай свой конец, что бы ни случилось. Я приплыву за ним сам. То, что я зачеркнул, было правдой. Пришлю ещё пирог, если найду муку.","chain":"rope_bucket","part":3},{"id":"flooded_012","kind":"note","title":"Записка в ведре","text":"Тоби, твоего дома не видно с пятницы, и плота твоего тоже. Верёвка уходит прямо в воду, но я её не отвязываю, ты же просил. Сегодня я вытянула ведро, и в нём лежали раковина и горсть ила. Отец говорит, чтобы я отошла от окна и поела. Опускаю тебе пирог с луком, ты такой любишь. Если это ты, потяни за верёвку.","chain":"rope_bucket","part":4},{"id":"flooded_013","kind":"note","title":"Наказ ученику","text":"Наказ первый, Робин, и запомни его, пока я добрый. Над Кожевенной улицей сети не бросай, они цепляются за вывески. Лучше всего ловится над лавкой Пегги, она всегда держала в подвале сыр, и рыба это помнит. Если зацепишь флюгер, дёргай вбок. Нож не доставай, сеть дороже флюгера. И не вздыхай, отец твой тоже всё путал, а рыбак вышел неплохой.","chain":"fisher_lessons","part":1},{"id":"flooded_014","kind":"note","title":"Наказ ученику","text":"Наказ второй, Робин. Если попалось что-нибудь, что не рыба, клади в ящик на корме и записывай, над чьим домом ты это взял, потому что на берегу люди спрашивают. Ложки свои Кобб забрал и плакал. Сапоги тоже забрал. Портрет тётки брать отказался наотрез, так что вези его обратно и опусти, где нашёл. Вещи людям отдавай без денег, у них больше ничего не осталось.","chain":"fisher_lessons","part":2},{"id":"flooded_015","kind":"note","title":"Наказ ученику","text":"Наказ третий, Робин, и матери твоей об этом ни слова. Над домом Уинтеров сети не бросай. Вытащишь, а рыба в сети уже выпотрошена и лежит ровно, головами в одну сторону, как складывала её покойная хозяйка. Есть такую рыбу или нет, решай сам. Я ел. Госпожа Уинтер всегда чистила рыбу лучше всех на улице, и у меня не хватило духу её обидеть.","chain":"fisher_lessons","part":3},{"id":"flooded_016","kind":"note","title":"Школьный журнал","text":"Школа госпожи Стерн. Занятия я перенесла на баржу. Присутствуют одиннадцать детей. Тема урока: реки нашего края. Дети справедливо указали, что река теперь одна и что она везде. Оценки я поставила всем, неделя у них и так была плохая.","chain":"school_barge","part":1},{"id":"flooded_017","kind":"note","title":"Школьный журнал","text":"Присутствуют девять детей, двое уехали с родителями на холм, и я этому рада. Тема: счёт. За ночь баржу снесло за мельницу, и Оливер спросил, считается ли это прогулом у всей школы сразу. Я поставила ему отметку за логику и оставила без обеда. Потом отдала ему свой.","chain":"school_barge","part":2},{"id":"flooded_018","kind":"note","title":"Школьный журнал","text":"Присутствует Оливер. Тема: чистописание. Когда он не спешит, то пишет очень хорошо. Отец обещал приплыть за ним в среду, а сегодня пятница. Завтрак мы разделили пополам. Он спросил, зачем я веду журнал для него одного, и я сказала, что так положено. Уроки будут идти, пока светло, чтобы он поменьше смотрел на воду.","chain":"school_barge","part":3},{"id":"flooded_019","kind":"note","title":"Метка на двери","text":"Здесь стояла вода в год большого сома. А здесь в год, когда Кейт вышла замуж и мы плясали на столах, чтобы не промочить ноги. Эту отметку отец сделал прошлой весной. Дальше дверь кончается, так что следующую, братец, будешь делать на втором этаже. Я свою очередь отработал."},{"id":"flooded_020","kind":"note","title":"Рост Пенни","text":"Пенни шесть лет. Пенни семь лет. Весной вода дошла Пенни до колена. Пенни восемь лет. Осенью вода дошла ей до пояса, и она сказала, что вода растёт быстрее и это нечестно. Пенни девять лет, отмечал уже на чердачной балке, потому что косяк теперь внизу. Ростом она пошла в отца, чем отец очень гордится."},{"id":"flooded_021","kind":"note","title":"Правила парома","text":"Не вставайте, пожалуйста. Скот заводите по одному. Плакать можно, петь только с разрешения кормчего. Покойников мы везём по полной цене, места они занимают столько же, и родня пусть на нас не обижается. Мокрые монеты принимаем, мокрые расписки нет."},{"id":"flooded_022","kind":"note","title":"Рецепт","text":"Щуку, дочка, готовь так. Сними чешую и вспори брюхо. Кольца, ложки и пуговицы из брюха складывай в миску у двери, вдруг хозяева придут спрашивать. Потом туши с луком час. Соль клади осторожно, соль нынче дорогая, а твой отец всё равно скажет, что недосолено."},{"id":"flooded_023","kind":"note","title":"Детской рукой","text":"сиводня мы ловили рыбу из окна спальни. папа сказал что теперь можно спать в лотке. ура. мама плакала и сказала что это изза лука. а у нас нет лука"},{"id":"flooded_024","kind":"note","title":"Ответ сборщику","text":"Сборщику податей. Вы прислали мне счёт за уборку Рыбной улицы. Рыбная улица лежит на глубине двенадцати футов. Я оплачу его, как только увижу там метлу и человека при ней. Вашей матушке поклон, мы с ней вместе ходили в школу, и считать она тоже не умела."},{"id":"flooded_025","kind":"note","title":"Объявление","text":"Утерян мост, каменный, с тремя пролётами. В последний раз его видели в четверг у Рыбных ворот. Нашедшего просят сообщить старосте, он сорок лет ловил с этого моста рыбу и очень тоскует. Гильдия паромщиков просит не сообщать."},{"id":"flooded_026","kind":"note","title":"Приказ цеха","text":"Приказ цеха рыбаков. Сети на Главной улице ставьте только по чётным дням. По нечётным там ходят свадебные лодки, и невесту Дженкинсов уже дважды вытаскивали вместе с уловом. Жених передаёт, что в третий раз заберёт её вместе с рыбой, и рыба пойдёт на свадебный стол."},{"id":"flooded_027","kind":"note","title":"Записка жене","text":"Энид, ты сказала, что уедешь к матери, как только вода дойдёт до порога. Третий год я каждую весну подкладываю под порог по кирпичу. Если дверь стала открываться туже, это от сырости. Пишу и прячу за печку, потому что вслух у меня не выйдет: я не хочу, чтобы ты уезжала."},{"id":"flooded_028","kind":"note","title":"Молитва","text":"Госпожа река, подвал возьми, раз уж взяла. Забор Кобба тоже можешь взять, забор всё равно плохой, а Кобб тридцать лет должен мне за курицу. Лестницу оставь, у меня колено. И прости, что я в тебя выливала. Самого Кобба, если можно, не топи, а то кто мне отдаст за курицу."},{"id":"flooded_029","kind":"note","title":"Надгробие","text":"Здесь лежит Гарольд Мосс, добрый муж. Сначала он лежал в саду, потом, когда сад залило, мы с соседями перенесли его на чердак, а теперь на крышу, к трубе, там теплее. Гарольд, не обижайся, что всё так наспех, спина у меня не новая. Я скучаю."},{"id":"flooded_030","kind":"note","title":"Расписка","text":"Я, Барт Квилл, взял у Джудит Фенн лодку на одну ночь, чтобы сплавать за бумагой, которая подтверждает, что дом на Мельничной улице мой. Бумагу я нашёл, а дома нет. Лодку верну в воскресенье, а бумагу могу оставить в залог. Джудит, не смейся, бумага очень хорошая, на ней есть печать."},{"id":"flooded_031","kind":"note","title":"Задача","text":"Задача. Вода прибывает на ладонь в день. До крыши осталось двенадцать ладоней. Сколько дней осталось Томасу? Решение ученика: Томас умеет плавать, это мой брат, и я сам его научил. Учитель: ответ принят с радостью, но перепиши и покажи действия."},{"id":"flooded_032","kind":"note","title":"Шутка","text":"Записал за Рори в таверне, чтобы рассказать жене, она любит про старост. Сколько старост нужно, чтобы объявить наводнение? Двое: один пишет приказ, а другой держит его за воротник над водой."},{"id":"flooded_033","kind":"note","title":"Кто черпает","text":"Кто вычерпывает воду: в понедельник Дагган, во вторник Дагган, в среду жена Даггана, в четверг Дагган, в пятницу Дагган. В субботу Дагган просит пересмотреть список. Напоминаю Даггану, что список он составил сам, на спор со мной, и спор этот проиграл. Твоя жена."},{"id":"flooded_034","kind":"note","title":"Новому гребцу","text":"Кто садится с сундуком, с того бери деньги вперёд. Кто всю дорогу смотрит за борт и молчит, того сажай на корму, поближе к себе, и денег с него не спрашивай. Кто спрашивает, сколько ещё плыть, тому говори, что скоро. И будь с ними поласковей, сынок, у них сегодня плохой день."},{"id":"flooded_035","kind":"note","title":"Письмо","text":"Дорогая моя Лиззи ... мы перебрались к дяде на холм и взяли только самое нужное, но твоё свадебное платье так и осталось на столе ... не возвращайся за ним, слышишь? Вода уже дошла до второго ... я тебя очень прошу. Платье я сошью новое, а другой дочери у меня нет. Твоя мама."},{"id":"flooded_036","kind":"note","title":"Письмо","text":"Сын мой ... в лодке не оставалось места для деда, и я сказала ему, что следующая придёт утром. Он поверил и сел ждать на крыше с собакой ... каждый вечер я ставлю лампу на окно, которое смотрит в ту сторону ... не говори отцу, что следующей лодки не было."},{"id":"flooded_037","kind":"note","title":"Приказ старосты","text":"Всем жителям приказываю немедленно перейти на верхние этажи. Кто останется в подвале после ... заплатит штраф четыре монеты. Исключение делается только для ... и для гусей. Штраф я соберу лично, как только научусь плавать. Жена меня уже учит."},{"id":"flooded_038","kind":"note","title":"Список долгов","text":"Альберт, сынок, если я не вернусь, вот кому я давал деньги. Нед Оуэн должен девять монет, но он утонул, и с него не бери. Дик Рэй должен четыре ... с его вдовы не спрашивай, ей и без тебя ... Том Каррик должен две монеты и лодку, он ещё жив, спроси у ..."},{"id":"flooded_039","kind":"note","title":"Рецепт лекаря","text":"Марта, от кашля давай ему ложку мёда и ... три дня подряд, на ночь. Ни в коем случае не ... иначе я за него не отвечаю. Младшему давай половину. И поспи сама, ты третью неделю на ногах."},{"id":"flooded_040","kind":"note","title":"Вывеска цирюльника","text":"Брею на втором этаже. С лодки я больше не брею, потому что порезал уже двоих. Один из них мой шурин, он теперь со мной не разговаривает, и мне это нравится. Стрижка по старой цене, вода в тазу бесплатно."},{"id":"flooded_041","kind":"note","title":"Записка на лестнице","text":"Дети, ваши кровати теперь на чердаке. Вниз не ходите, вода стоит уже на пятой ступеньке, я вас очень прошу. Если снизу позовут ужинать, это не я. Я зову только с верхней ступеньки и всегда сначала говорю, что на ужин. Целую вас, мама."},{"id":"flooded_042","kind":"note","title":"Приглашение","text":"Роза Марлоу и Дункан Фэрроу приглашают вас на свадьбу в субботу у колокольни. Лодки привязывайте к южному окну. Гостей просим приплыть сухими, насколько получится. Подарки дарите только такие, что держатся на воде. Тётя Эдит, вас особенно просим не плакать, вода и так высокая."},{"id":"flooded_043","kind":"note","title":"От звонаря","text":"Колокол теперь бьёт сам, когда вода качает язык. Прошу не приходить ко мне с жалобами в три часа ночи. Я живу через улицу, и мне слышно лучше всех. Если вам не спится, приплывайте с вином, посидим и послушаем вместе, звонит он всё-таки красиво."},{"id":"flooded_044","kind":"note","title":"Поправка к плану","text":"Поправка к городскому плану. Улицу Сукновалов читайте теперь как пролив Сукновалов. Площадь Четырёх Ветров считайте заливом. Номера домов остаются прежние, просьба отсчитывать их от воды. Картограф просит передать жене, что к ужину не придёт, город всё ещё меняется."},{"id":"flooded_045","kind":"note","title":"Книга повитухи","text":"Мальчик, пять фунтов, родился на лестнице между вторым и третьим этажом, потому что ниже было мокро, а выше мы не дошли. Мать спрашивает, что писать в графе о месте рождения. Я записала: дом Трентов, пока что. Мальчик кричит громко, мать смеётся и плачет, и я вместе с ней."},{"id":"flooded_046","kind":"note","title":"Дневник","text":"Моя собака Бланш опять нырнула и принесла башмак. Все башмаки левые и все разные, а сегодняшний детский. Я складываю их у печи сушить и за каждый даю ей кусок рыбы, она так старается. Соседи говорят, что я странная, но никто из них пока не пришёл спросить, чьи это башмаки."},{"id":"flooded_047","kind":"note","title":"Книга сапожника","text":"Заказы на неделю. Кэмпбелл заказал сапоги до колена. Дюран заказал до бедра, чтобы было выше, чем у Кэмпбелла. Кэмпбелл заказал до пояса. Дюран теперь спрашивает, можно ли с рукавами. Они соседи и сорок лет друг с другом не разговаривают. Кожи у меня осталось на один заказ, и я боюсь решать, кому его отдать."},{"id":"flooded_048","kind":"note","title":"Обход домов","text":"Обход домов. В доме Кроули вода поднялась на три ступени, жильцы говорят, что пока терпимо. В доме Рена поднялась на девять ступеней, там тоже говорят, что пока терпимо. В доме Флинта вода стоит выше окон. Я постучал веслом по ставню, и изнутри мне сказали, что пока терпимо. Дальше я не поплыл. Старосте напишу, что все бодры."},{"id":"flooded_049","kind":"note","title":"Уведомление","text":"Жильцу Дойлу. Первый этаж я больше не сдаю по причине реки. Плату за него переношу на второй, так как дом у меня один. Прошу вас не присылать больше рыбу в счёт долга, у меня её полный коридор. Вы хороший человек и плохой жилец, и моя жена велит спросить, есть ли у вас сухие носки."},{"id":"flooded_050","kind":"note","title":"Детской рукой","text":"мы с вилом считаем сколько ступенек на леснице осталось до воды. вчира было девять сиводня восемь. вил говорит что вода тоже учится считать только назад. мама сказала хватит глупостей идите есть. а ночю я видел как она сама вышла со свечкой и считала"},{"id":"flooded_051","kind":"note","title":"Отчёт фонарщика","text":"Отчёт фонарщика. На Рыбной я зажёг четыре фонаря с лодки. На Кожевенной тоже с лодки, там остались одни верхние кронштейны. Ниже Кожевенной под водой горит ещё один, на углу у аптеки. Я его не зажигал. Масла он не просит, поэтому в отчёт его не вношу. Старая Мейзи из аптеки всегда просила меня не забывать про её угол, и по вечерам я подплываю с ним поздороваться."},{"id":"flooded_052","kind":"note","title":"Купчая","text":"Продан дом с садом на Мельничной улице господину Пру. Покупатель осмотрел сад с лодки, шестом, и претензий не имеет. Яблони плодоносят, со слов продавца. Продавец просил записать, что это был дом его матери и что ему очень жаль."},{"id":"flooded_053","kind":"note","title":"Что нести наверх","text":"Надо отнести наверх муку, одеяла, зеркало тёти и кровать деда. Дед пока идти не хочет, говорит, что у него внизу дела. Спросить его поласковее, какие там могут быть дела. Бабушкино кресло всё ещё стоит внизу, и он каждый вечер с ним разговаривает."},{"id":"flooded_054","kind":"note","title":"Записка библиотекарю","text":"Дорогая госпожа Брандон, возвращаю «Уход за садом» с опозданием в четыре года. Простите за вид. Сада у меня теперь нет, и дочитывать незачем. На странице сорок кто-то живёт, я его не трогала и вас прошу не трогать. Вы всегда были ко мне добры, даже когда я брала книги грязными руками."},{"id":"flooded_055","kind":"note","title":"Записка соседке","text":"Кэтрин, я тут родилась и никуда не поеду, так и скажи своему сыну, хотя спасибо ему, что волнуется. А вчерашний стул, будь добра, забери и принеси тот, что повыше, у этого вода уже дошла до сиденья. И приходи посидеть, я соскучилась."},{"id":"flooded_056","kind":"note","title":"Надпись на стене","text":"Здесь был Рори Гленн. Вода здесь была уже потом."},{"id":"flooded_057","kind":"note","title":"Из бутылки","text":"Нас девять на колокольне, дядя Арчи десятый, но он спит. Если найдёшь это письмо, пришли лодку. Если лодки нет, пришли соли. Рыбу без соли есть уже никто не может, и мы начинаем ссориться. Моя жена третий день не разговаривает со своей сестрой, и за это я реке благодарен, но соли всё равно пришли."},{"id":"flooded_058","kind":"note","title":"Рынок на крышах","text":"По четвергам рынок проводится на крышах. Мясной ряд идёт от дома Гиббса до трубы Кейна, а овощной стоит на сарае вдовы Тейт, пока сарай держит. Просим покупателей не заглядывать в слуховые окна, там живут люди. Вдове Тейт от всего рынка спасибо и пирог."},{"id":"flooded_059","kind":"note","title":"Жалоба старосте","text":"От Поттеров с третьего этажа. Соседи снизу поют по вечерам. Соседей снизу нет с апреля, они уехали к родне, и я сам помогал им грузить сундуки. Поют они неплохо, но всё одно и то же, и моя жена начала подпевать. Прошу принять меры, пока она не выучила второй куплет."},{"id":"flooded_060","kind":"note","title":"Дневник","text":"Купил гуся. Дорого, и кормить его нечем. Дома все третью неделю ходят мокрые и злые, а он плавает по кухне и разговаривает. Дочка сегодня смеялась, впервые за месяц. Ему хорошо, пусть живёт."},{"id":"flooded_061","kind":"note","title":"Альманах","text":"Весна ожидается сухая, лето жаркое, реки мелкие. От издателя: приносим извинения, типография переехала на чердак, и тираж подмочен. Исправления выйдут, как только найдётся наш наборщик. Альфред, вернись, мы на тебя не сердимся."},{"id":"flooded_062","kind":"note","title":"Протокол собрания","text":"Собрание квартала Тростника решило на холм не переезжать, потому что земля там дорогая, а родня противная. Будем надстраивать. Каменщик Кейн говорит, что этаж в год выдержит любой дом, если не жалеть раствора. Голосовали поднятием рук, Кейн поднял обе. Родня с холма прислала сказать, что всё слышала и ждёт нас к ужину."},{"id":"flooded_063","kind":"note","title":"На двери","text":"Ворам. Внизу брать нечего, всё наверху. Наверху живём мы, нас шестеро, и у всех есть вёсла. Бабушка просила написать, что у неё весло самое большое."},{"id":"flooded_064","kind":"note","title":"Объявление","text":"Продаю дело водоноса: два ведра, коромысло и постоянных покупателей на Рыбной улице. Причина продажи видна из окна."},{"id":"flooded_065","kind":"note","title":"Записка капитана","text":"Последняя лодка на холм отходит с рассветом. На доске я написал, что завтра будет ещё одна. Завтра её не будет, и знаю об этом только я. Если сказать правду, у причала затопчут малых, поэтому детей я беру без очереди и слежу за этим сам. Пишу, чтобы это было хоть где-то сказано."},{"id":"flooded_066","kind":"note","title":"Распоряжение","text":"Приказываю перенести огонь с площади на второй этаж ратуши, а когда вода дойдёт и туда, на чердак. Старик, который смотрит за углями, просит сухих дров. Сухих дров нет. Выдайте ему хотя бы стул, и пусть уже не просит. Я знаю, что он устал, он сидит там столько, сколько я себя помню."},{"id":"flooded_067","kind":"note","title":"Счёт из таверны","text":"Шкипер Дарби, «Сухой угол», второй этаж. Шесть кружек эля и сельдь. Дверь под водой, поэтому ушёл ты через окно и разбил его. Потом вернулся через окно и выпил ещё две кружки. Окно пишу один раз, оно уже было разбито. Дарби, родной, заплати, я же знаю твою мать."},{"id":"flooded_068","kind":"note","title":"Отцовский наказ","text":"Сын, соль пробуй языком, весам не верь. Речные торговцы кладут в неё песок, горные мел, а дядя твой кладёт и то и другое и ещё обижается. За солью к нему не ходи. На похороны его сходи, он всё-таки мой брат, и я его любил, хоть ни разу ему этого не сказал."},{"id":"flooded_069","kind":"note","title":"Письмо жениху","text":"Господину Тиму Арно. Вы просите руки нашей Лоры. У речных так: сначала дядя осмотрит днище вашей лодки, потом тётя посмотрит ваши зубы. Если дядя останется доволен, зубы смотреть не будем. Лора велела добавить, что лодка у вас хорошая, а откуда она это знает, мы с ней ещё поговорим. Её мать."},{"id":"flooded_070","kind":"note","title":"Дневник вдовы","text":"Чердак маленький, и вещей я взяла мало. Две миски зачем-то взяла. Свою разбила на лестнице и ем теперь из Рэндаловой. На донышке у неё вырезано: «Жена, добавки». Тридцать лет я её мыла и думала, что это царапины. Будет тебе добавка, дурак ты мой, когда увидимся."},{"id":"flooded_071","kind":"secret","title":"Промеры","text":"Брат, ты один у нас умеешь считать, проверь меня, я очень хочу ошибиться. Я сверил воду по Верхнему камню на холме, и сверил трижды. За десять лет река не поднялась ни на ладонь. Поднимаются только метки на наших дверях, по ладони в неделю. Выходит, река стоит на месте, а вниз едет весь город. Старосте я не докладываю, он только что заказал новые лестницы и впервые за год доволен."},{"id":"flooded_072","kind":"secret","title":"Записка в стене","text":"Тем, кто когда-нибудь построит дом у меня на крыше. Дубовая балка над южным окном цела, берите её, послужит ещё. Колодец на заднем дворе копать не советую, там наша кухня. В жестянке за кирпичом лежат кремень, трут и немного табака. Простите, если табак плох. Мы тут хорошо жили и желаем вам того же."},{"id":"flooded_073","kind":"secret","title":"Письмо внучке","text":"Дорогая моя, мой дед показывал мне записки своего деда. Там говорится про старика, который сидит при огне на площади, и горшок с углями у него такой же, как у нашего, и должен он всем в городе, точь-в-точь как наш. Я как-то спросила нашего старика, сколько ему лет. Он сказал, что дрова кончаются, и попросил подбросить. Спроси у него ты, он к тебе добрее."},{"id":"flooded_074","kind":"secret","title":"Тайный счёт","text":"Везём соль на север, без пошлины, в шести гробах, по два мешка в каждом. С нами едут трое плачущих, по монете на каждого. Тётя Мод плачет лучше всех, ей бы надо платить две. Седьмой гроб дядя велел взять с настоящим покойником, для вида. Покойнику тоже запишем монету, он хорошо держался."},{"id":"flooded_075","kind":"secret","title":"Записка ныряльщика","text":"Нырял за кольцом жены у Рыбных ворот, она плакала о нём целую неделю. Мостовая там обрывается, дальше идёт провал, и из него поднимается тепло, как от печки. Камни на краю старой работы, клейма на них чужие. Вода над провалом всё время мелко дрожит, как рука у того, кто долго несёт тяжёлое. Кольцо я не нашёл. Жене сказал, что нырну ещё раз, а сам боюсь."},{"id":"flooded_076","kind":"secret","title":"Клад","text":"сдесь лежит клад братства красной шапки. три пуговицы. зуб это мой. монета но не настоящая. кто возьмёт тот наш брат навсегда и должен положить ещё чтонибудь. мы уезжаем на холм. эмма плачет потомучто ей жалко но она сестра ей можно. присматривай за кладом пожалуста"},{"id":"flooded_077","kind":"secret","title":"Признание","text":"Отец Мартин, вслух я этого сказать не могу. Три года я рисовал на дверях следы воды, по медяку за метку, чтобы квартал получал пособие за потоп, которого не было. Выводил ровно, с потёками, и люди меня хвалили. В ту осень вода поднялась в точности до моих меток, дом за домом. Теперь соседи просят нарисовать им метки пониже, и я рисую. Скажите мне, пожалуйста, что это не я."},{"id":"flooded_078","kind":"secret","title":"Записка мужу","text":"Фред, ты думаешь, что я спустила деньги на шляпы. Шляпы сестрины. Деньги здесь, в этой жестянке, сорок две монеты на дом на холме. Я скажу тебе, когда наберётся пятьдесят, хочу посмотреть на твоё лицо. Если ты нашёл это раньше, положи обратно и сделай вид, что не находил."},{"id":"flooded_079","kind":"secret","title":"Записка крысолова","text":"Крысы ушли с Кожевенной за три недели до воды, все до одной, в сторону холма. Я взял с квартала плату и сказал, что это моя работа. На эти деньги я купил лодку. Никому об этом не говорил, даже жене. Лодка хорошая, и когда пришла вода, я вывез на ней всю Кожевенную и ни с кого не взял ни монеты. Может быть, теперь мы квиты."},{"id":"flooded_080","kind":"secret","title":"Про шкаф","text":"Сэм, ты мой лучший друг, поэтому говорю только тебе. Лестница за шкафом ведёт на чердак Мэттисов. Про неё знаем мы с Линдой и теперь ты. Тридцать лет мы ходили друг к другу, и муж её так и не понял, отчего у них пахнет моим табаком. Если встретишь её наверху, передай, что шкаф я отодвинул и вода туда не дошла. Пусть приходит, как раньше."},{"id":"flooded_081","kind":"boss","title":"Предание","text":"Паромщик брал по две монеты с головы. В ночь большой воды он не взял ни с кого и нагрузил лодку так, что она ушла на дно. Выплывшие говорили, что он держал её снизу, на спине, пока последний не вылез на крышу. На следующую ночь кто-то постучал снизу в борт чужой лодки, два раза, как монетами о дерево.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_082","kind":"boss","title":"Книга сборов","text":"Неделя перед паводком. Вдова Ларк с двумя детьми заплатила шесть монет, младшему я дал сушёной рыбы. Мясник с тушей заплатил четыре. Священник заплатил две и просил скидку от имени небес, я отказал. Старик с горшком углей обещал отдать две монеты на обратном пути и поехал в долг. Горшок он всю дорогу держал на коленях и грел руки, и за горшок я с него не взял.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_083","kind":"boss","title":"Книга сборов","text":"Ночь воды. Пишу, пока грузятся. От Рыбных ворот я перевёз сорок человек и платы не взял. С Кожевенной двадцать шесть, платы не взял. На Тростниковой сажаю, сколько влезает, и уже не считаю. Лодка моя берёт двенадцать, это я знаю лучше всех. Если эту книгу найдёт моя дочка, пусть знает, что долгов за этой ночью ни на ком нет и взыскивать ни с кого не надо.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_084","kind":"boss","title":"Показания","text":"Показания Агнес Ларк писарю квартала. Лодка пошла вниз, вода была мне уже по грудь, младшего я держала на руках, и тут под ногами стало твёрдо. Оно было шершавое и двигалось. Писарь просит уточнить, на чём я стояла. Я не знаю, на чём, но я стояла, и дети мои стояли. Писарь просит уточнить, отчего я плачу. Этого, милый, не записывайте.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_085","kind":"boss","title":"Детской рукой","text":"дяденька паромщик сказал садись не бойся. лотка утонула а мы неутонули. под нами было большое и скользкое. я постучал ему два раза чтобы сказать спасибо. мама говорит что я это придумал. а он мне тоже постучал","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_086","kind":"boss","title":"Записка рыбака","text":"Нелл, я сказал тебе, что рыба не идёт, но это неправда. Пишу, потому что вслух ты засмеёшься. Я вышел затемно к Мельничной, и снизу в борт постучали два раза, ровно, как монету на лавку кладут. Я сказал, что денег при себе нет. Оно подождало и постучало опять. Тогда я смотал сети и поплыл домой пустой. Дай мне завтра немного мелочи, родная, и ни о чём не спрашивай.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_087","kind":"boss","title":"Приказ гильдии","text":"Гильдия лодочников всем своим. На стук снизу не отвечайте. Монеты за борт не бросайте, касса и так пуста. Кто услышал стук, пусть запишется у старшины, чтобы мы понимали, где он сегодня ходит. За месяц записано тридцать один раз. Никто не пострадал, кроме Дэви, он упал со страху с собственной лодки. Дэви, мы за тебя переживаем, и верни багор.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_088","kind":"boss","title":"Письмо отцу","text":"Отец, я сделала, как ты велел: бросила за борт две монеты, за тебя и за мать, за ту ночь, чтобы вы никому не были должны. К утру обе лежали в лодке на скамье, мокрые, ровно положенные, и на одной была твоя зарубка. Стук был слабый, как будто он устал. Что с ними делать, я не знаю, пока держу в чашке. Береги спину и напиши мне, что думаешь.","boss":"boss_serpent","floors":[9,12]},{"id":"forge_001","kind":"note","title":"Список покупок","text":"Нэнси, детка, сходи на этой неделе на рынок, у меня прихватило спину. Купи два мешка угля и новый фартук для Дэйви, старый он совсем прожёг. Возьми большой горшок гусиного жира, потому что отец опять обжёг руки и молчит, думает, что я не вижу. Масло не бери, оно у нас всё равно растечётся по полке. И спроси у Мод, почём теперь лёд и есть ли он ещё вообще. Сдачу оставь себе на ленту."},{"id":"forge_002","kind":"note","title":"Приказ по цеху","text":"Подмастерьям запрещается жарить колбасу на заготовках мастера. Вчера заказчик спросил, почему его подкова пахнет чесноком, и мастер не нашёлся, что ему ответить, а он за сорок лет всегда находился. За каждую колбасу назначаю штраф три медяка. Найденную колбасу несите старшине, он разберётся с ней лично. Ребята, я тоже был молодым и голодным. Жарьте на совке, как все люди."},{"id":"forge_003","kind":"note","title":"Книга водоноса","text":"Я принял Литейный колодец, плата по медяку с двора. Вода в этом году теплее прошлогодней, и хозяйки мне радуются: стирать легче, руки не стынут. Вдова Лорси принесла мне пирог с капустой и спросила, не тяжело ли мне таскать вёдра. Я ответил, что нет. Если она спросит ещё раз, скажу, что тяжело.","chain":"forge_well","part":1},{"id":"forge_004","kind":"note","title":"Расписка","text":"Я получил от вдовы Лорси шесть серебряных за кованую оградку на могилу её мужа. Она просила сделать оградку повыше. Я спросил, зачем ей повыше, человек там теперь лежит смирно. Она молча доложила ещё одну монету. Покойного я знал тридцать лет, так что вопросов у меня больше нет."},{"id":"forge_005","kind":"note","title":"Табличка","text":"Если у вас пожар, стучите громче, мы тут все оглохли от молотов. Если просто горит, значит, это литейная, и вы можете идти дальше."},{"id":"forge_006","kind":"note","title":"Детской рукой","text":"папа сказал нелзя ходить босиком по двору а я ходил. теперь у меня на пятке картинка как решотка. мама мазала жиром и ругалась а потом поцеловала пятку. Нэд дал мне два ореха чтобы посмотреть. папе не скажу что картинка красивая"},{"id":"forge_007","kind":"note","title":"Требования","text":"Старшинам цеха от подмастерьев Угольного ряда. Мы требуем смену в десять часов, воду за счёт цеха и двойную плату за ночную работу. Фартуки прожигаются от работы, поэтому перестаньте вычитать за них из жалованья. Жёны и матери видят нас только спящими и уже спрашивают, как нас зовут. Пока нам не ответят, мы к горнам не подойдём. Подписали двадцать шесть человек. Дэйви поставил крестик, потому что пока учится писать.","chain":"forge_strike","part":1},{"id":"forge_008","kind":"note","title":"Правила литейной","text":"1. Фартук надевай до того, как подошёл к печи. 2. Ковш через голову товарища не передавай, у него есть мать. 3. Воду в форму не лей, сколько бы тебя ни просили и кто бы ни просил. 4. Если со стороны печи тебя позовут по имени, молчи и иди к мастеру, даже если голос похож на голос твоего отца."},{"id":"forge_009","kind":"note","title":"Рецепт","text":"Дочка, ты просила рецепт нашего хлеба, записываю. Тесто замеси с вечера, положи на порог и накрой мокрой тряпкой. К утру оно испечётся само, потому что порог у нас теперь горячий, а печку мы не топим с прошлой зимы. Корка снизу выходит чёрная, её срежь ножом и отдай собаке, собака у нас неразборчивая, в отца. У тебя в Холлоу порог, наверное, холодный, так что не знаю, как ты там вообще живёшь. Ты хоть ешь?"},{"id":"forge_010","kind":"note","title":"Записка","text":"Гвен, я выковал тебе колечко из того самого гвоздя, который ты уронила мне на ногу в день нашего знакомства. Размер я угадал по тому, как ты держишь кружку. Если окажется велико, скажи, я переделаю, нога у меня уже зажила. Выходи за меня, пока я не растерял смелость. Гвоздей у меня полный двор, а ног только две."},{"id":"forge_011","kind":"note","title":"Письмо домой","text":"Матушка, я доехал и жив. Мастер у нас строгий, зато кормят супом, и кровать у меня своя, мы спим на ней вдвоём с Лукасом. Лукас хороший, он делится со мной хлебом. Тут очень тепло, ты зря положила мне шерстяные чулки. Посылаю их обратно с возчиком, продай их, кому нужнее. Сегодня мне дали качать мехи, и мастер сказал, что я дую как чайник. Я пока не понял, хорошо это или плохо. Я скучаю по тебе. Поцелуй за меня Бесс.","chain":"forge_letters","part":1},{"id":"forge_012","kind":"note","title":"Надгробие","text":"Здесь лежит Уилмот Кросс, клепальщик. Сорок лет соседи жаловались, что он стучит. Теперешние соседи могут быть спокойны. Жена велела дописать, что дома ей стало слишком тихо и что она бы ещё послушала."},{"id":"forge_013","kind":"note","title":"Счёт из трактира","text":"Трактир «Кривой ковш», счёт Роланда Тэйта за неделю. Эля он выпил четырнадцать кружек, это семь медяков. Кружка холодной воды стоит два серебряных, и он заказал одну. Долг я записал. Роланд, ты мне как брат, поэтому скажу прямо: воду ты пил сидя, не торопясь и с закрытыми глазами, и я впервые за год видел тебя счастливым. Проценты с этого долга я брать не стану."},{"id":"forge_014","kind":"note","title":"Книга водоноса","text":"Хозяйки теперь варят яйца прямо в колодце, опускают их в мешочках на бечёвке. Я беру полмедяка за мешочек, старшина разрешил. Ведро достаю в рукавицах, а верёвку сменил на цепь, потому что старая стала ломкой. Вдова Лорси велела мне беречь руки и принесла рукавицы своего мужа, сказала, что ему они теперь ни к чему. Они мне малы, но я их ношу.","chain":"forge_well","part":2},{"id":"forge_015","kind":"note","title":"У горна","text":"Оуэна мы схоронили в воскресенье, и дежурить у горна теперь приходится мне, Бертраму. Мы с ним дружили с ученичества. С той недели угля в горне каждое утро больше, чем я клал вечером. А вчера в списке дежурных кто-то вписал без меня: Оуэн. Его почерк я знаю сорок лет. Стирать я не стал и принёс ему табаку."},{"id":"forge_016","kind":"note","title":"Школьная задача","text":"Один подмастерье куёт двенадцать гвоздей в час. Сколько гвоздей он выкует за смену, если смену продлили, а потом продлили ещё раз? Ответ ученика: столько, сколько скажет мастер. Пометка учителя: верно, садись. И передай отцу, чтобы хоть в воскресенье поспал."},{"id":"forge_017","kind":"note","title":"Ответ цеха","text":"Подмастерьям Угольного ряда. Про воду мы поговорим. Про ночные смены тоже поговорим. Фартуки прожгли вы сами, поэтому они ваши. Старшины напоминают, что большой заказ не может стоять. Кто не выйдет к горнам в понедельник, не получит ни платы за неделю, ни рекомендации. Приписка писаря, не для собрания: Гаррет, твоя мать приходила ко мне и плакала. Выйди в понедельник, прошу тебя как дядя.","chain":"forge_strike","part":2},{"id":"forge_018","kind":"note","title":"Шутка на свадьбу","text":"Это для свадьбы Дункана, скажу за столом, если мне нальют. Спросили кузнеца: что жена говорит про твой стук? Он отвечает: ничего не говорит, двадцать лет молчит, золотая женщина. Спросили жену. Та отвечала очень долго, но кузнец не расслышал ни слова. Надо бы дописать что-нибудь про тёщу, только сначала узнаю, где она будет сидеть."},{"id":"forge_019","kind":"note","title":"Молитва","text":"Святая Морвен, держащая огонь в ладони, сделай так, чтобы у моего Фенвика зажила рука и он снова взял клещи. Если нельзя клещи, пусть возьмёт хотя бы ложку, а то кормлю его я, и он от этого злится и стыдится. Я тридцать лет люблю этого сварливого человека. Свечу я тебе поставлю, как только свечи у нас перестанут гнуться от жары."},{"id":"forge_020","kind":"note","title":"Жалоба в цех","text":"Третий раз прошу цех что-нибудь сделать со стеной литейной, к которой прибиты мои сушильные верёвки. Бельё сохнет быстрее, чем я успеваю сходить за вторым тазом. Вчера две простыни сгорели прямо на верёвке, причём сама верёвка цела. Эти простыни мать подарила мне на свадьбу, и муж спал на них до самого конца. Прошу возместить. Корделия Брам, Мехов переулок."},{"id":"forge_021","kind":"note","title":"Объявление","text":"Продаю чугунную печь, почти новую, в нашем доме она больше не нужна. Отдам также шесть зимних одеял и детские сани, на которых мои дочки катались, пока на улице ещё лежал снег. Сани жалко, хорошие были сани. Спросите Найджела на Угольном ряду, если я ещё не уехал."},{"id":"forge_022","kind":"note","title":"Письмо домой","text":"Матушка, пришли мне мази и сушёных яблок, если сможешь. Меня поставили к средней печи и платят на медяк больше, так что скоро я пошлю тебе денег. Лукаса поставили к большой. Спать он теперь не приходит, говорит, что ему некогда. Кровать вся моя, а мне почему-то не спится. Я всё думаю, что надо было сказать ему, чтобы поел.","chain":"forge_letters","part":2},{"id":"forge_023","kind":"note","title":"Нужен ученик","text":"Двору Хэдли нужен ученик, крепкий и непьющий, который не боится жары. Кормим два раза в день, а жена мастера подкладывает третий, когда он не смотрит. Про брови просим не спрашивать, они отрастают."},{"id":"forge_024","kind":"note","title":"Расчётный лист","text":"Ансельм Хоук, молотобоец. Жалованье за месяц составило двенадцать серебряных. Вычеты такие: за фартук два, за уголь, потраченный без нужды, один, складчина на поминки старшины три, лекарю пять. На руки выдано одно серебряное. Подпись за Ансельма ставлю я, новый старшина, потому что пальцы у него не сгибаются. Его жена пришла за деньгами и долго смотрела на эту монету. Я добавил ей свою, в книгу не пишу."},{"id":"forge_025","kind":"note","title":"Книга водоноса","text":"Ведро приходит наверх наполовину пустым, остальное уходит паром, пока я его поднимаю. С утра я разливаю воду по корытам, чтобы до обеда остыла. Дети спрашивают меня, кто стучит внизу. Я сказал им, что это ведро бьётся о камни. Дети поверили, а вдова Лорси посмотрела на меня и ничего не сказала. Она-то видела, что ведро в тот час стояло на земле.","chain":"forge_well","part":3},{"id":"forge_026","kind":"note","title":"Наказ сыну","text":"Дэйви, сынок, я поехал к тёще и вернусь в среду. Держи горн ровно и качай мехи так, как я тебе показывал, а не так, как ты любишь. Кочергу отнеси вдове Лорси и денег с неё не бери, она нас кормила, когда я болел. Если средняя печь запоёт, сразу закрой заслонку и иди ночевать домой, ничего там не жди и не слушай. Ключ я оставил под ведром. Ешь как следует, я спрошу у матери."},{"id":"forge_027","kind":"note","title":"Опись","text":"Опись имущества покойного Тибальда Фрея, составил его сын. Наковален осталось две, молотов девять. Клещей одиннадцать пар, и одна пара сжата так, что мы вдвоём с братом не смогли её разжать. Внутри что-то есть, и оно тёплое, поэтому мы оставили всё как было. Мехи дырявые. Долгов за отцом нет, он всю жизнь этим гордился и велел написать отдельно."},{"id":"forge_028","kind":"note","title":"Дневник","text":"Я делал пряжку для невесты Эдвина, и получилась она только с пятого раза. Бертрам говорит, что она похожа на лягушку. Это лебедь. Невеста взяла пряжку, поцеловала меня в щёку и спросила, как я догадался, что она любит лягушек. Бертраму я об этом не скажу до самой его смерти."},{"id":"forge_029","kind":"note","title":"Письмо поставщика","text":"Господа старшины! Последняя подвода льда доехала до ваших ворот мокрой телегой. Возница, мой родной брат, клянётся, что лёд на ней был, и я ему верю, хотя он мне должен. Счёт прилагаю полный. Лошадь в ваш квартал больше не идёт, она встала на перекрёстке и смотрит на брата с укоризной, так что дальше возите сами."},{"id":"forge_030","kind":"note","title":"Листок стачки","text":"Идёт шестой день стачки. Мы сидим у ворот, на хлеб пока хватает, а мать Гаррета носит нам суп, ругает всех по очереди и всё равно наливает добавку. К горнам никто из нас не подходил, ключи у нас, и ворота я запирал сам. А дым из труб идёт, как шёл.","chain":"forge_strike","part":3},{"id":"forge_031","kind":"note","title":"Вывеска сапожника","text":"Делаю подмётки для Литейной. Двойные продержатся месяц. Тройные продержатся месяц и неделю. Четверные я вам не советую, споткнётесь, как мой зять. Стивен Гейл, у фонтана. Фонтан не работает, а я пока работаю."},{"id":"forge_032","kind":"note","title":"Письмо сестре","text":"Марджери, мы перебрались на верхний этаж, потому что внизу стало не уснуть от жары. Хозяин взял за это ещё медяк. Петух во дворе кричит всю ночь: небо у нас красное, и он думает, что настало утро. Муж грозится его сварить, а сам каждый вечер кормит с руки. Приезжай, сестричка, на именины и привези ведро снега, если он где-нибудь ещё лежит. Я скучаю по снегу, но по тебе больше."},{"id":"forge_033","kind":"note","title":"Письмо домой","text":"Матушка, пишу быстро, мастер ждёт. Деньги за три месяца тебе передадут, на меня их не трать. Вчера Лукас вышел к ужину, брал еду руками прямо из кипящего котла и не морщился. Он посмотрел на меня и не вспомнил, как меня зовут. Завтра меня тоже ставят к большой печи, мастер сказал, что я готов. Пришли мне всё-таки те чулки, если ты их не продала. Ночью мне стало холодно, матушка, а здесь никому не бывает холодно.","chain":"forge_letters","part":3},{"id":"forge_034","kind":"note","title":"Донесение","text":"Старшине от трубочиста. Трубы на Молотовой я проверил, они чистые, и тяга ровная. Спросил печников про дом Бенедикта, потому что печи у него нет вовсе, а дым идёт из-под пола. Печники сказали, что это не к ним. Бенедикт мне кум, и дети у него кашляют, так что прошу вас, пошлите к нему хоть кого-нибудь, пока он сам не начал копать."},{"id":"forge_035","kind":"note","title":"Договор","text":"Мальчик Пип девяти лет отдан в ученье мастеру Хэдли на семь лет. Мастер обязуется дать ему кров и ремесло. Отец получил за него два серебряных. Мать просила вписать, чтобы её сына не ставили к большой печи, и ещё, что он боится темноты и засыпает, только если ему споют. Всё это вписано на полях. Законной силы приписка не имеет. Мастер прочитал и сказал, что петь не умеет, но попробует."},{"id":"forge_036","kind":"note","title":"Книга водоноса","text":"Сегодня я опустил ведро, а поднял цепь без ведра. Конец цепи стал мягким, как тесто, и светился. Старшина выдал мне жалованье вперёд и велел закрыть колодец. Каменная крышка треснула за ночь, поэтому кладём железную. Я ходил спрашивать про работу на мельнице и сказал вдове Лорси, что там хватит места на двоих. Она ответила, что подумает, и вынесла мне пирог в дорогу, хотя я ещё никуда не еду.","chain":"forge_well","part":4},{"id":"forge_037","kind":"note","title":"Заявка каменщику","text":"Мастер Клемент, порог у нас оплыл, как воск. С утра камень тёплый, к вечеру мягкий, и дверь снизу прихватило так, что она больше не открывается. Поправьте, пожалуйста, когда сможете. Пока мы ходим через окно. Жена лезет первой и ругает меня всю дорогу, а вчера застряла, и мы с ней впервые за год посмеялись. Бенедикт говорит, что у него то же самое."},{"id":"forge_038","kind":"note","title":"Порядок праздника","text":"Утром мы пройдём шествием с молотами. В полдень начнётся бег с наковальней, победитель получит окорок. Вечером старшины будут петь. Просим вас не расходиться раньше времени, в прошлом году они обиделись и плакали. Купание отменяется, потому что пруд опять кипит. Матери, присмотрите за детьми, особенно за Нэдом."},{"id":"forge_039","kind":"note","title":"Записка","text":"Рейнольд, брат, ребята спрашивают, что им делать. Сегодня ночью в запертых цехах опять стучали молоты. Мы заглянули в щель: горны гудят, а на наковальнях лежит готовое железо, ещё тёплое. Ворота заперты, ключи при мне, там никого не может быть. В понедельник многие выйдут на работу. Я тоже выйду, прости меня, у Кэтрин скоро срок. Не сердись и приходи крестить.","chain":"forge_strike","part":4},{"id":"forge_040","kind":"note","title":"Сбор железа","text":"На нужды совета собираем с каждого двора по ведру лома. Это уже восьмой сбор за год. Кто уже сдал котлы и вилки, может сдать дверные петли: двери мы всё равно держим открытыми от жары. Тётя Мод, не смотрите на меня так, я свою ложку сдал первым."},{"id":"forge_041","kind":"secret","title":"Секрет закалки","text":"Три поколения двор Хэдли хранит секрет закалки: железо надо калить в молоке рыжей козы, взятом до восхода. Отец шепнул мне это перед смертью и заплакал. Я всё проверил. В простой воде выходит то же самое. Сыну я про козу всё равно скажу, пусть и ему будет что шептать. Молоко я, кстати, пил."},{"id":"forge_042","kind":"secret","title":"Признание","text":"Кому-нибудь я должен признаться. Ночью я подпилил звено до половины, чтобы цепь лопнула, всё кончилось и мой сын пришёл наконец домой. Наутро пропил был заварен, и звено стояло целое. Рядом появилась зарубка, глубже и ровнее моей, как будто мне показали, как надо было пилить. На наковальне лежала моя пила, и кто-то её заточил. Сын утром спросил меня, хорошо ли я спал. Он никогда раньше такого не спрашивал."},{"id":"forge_043","kind":"secret","title":"Рассказ деда","text":"Дед говорил, что огонь в главном горне принесли снизу, из города, который был тут раньше. Принёс его старик на лопате и спросил у первых кузнецов, почему они так долго. Дед божился, что видел того же старика на прошлой неделе у рынка. Глаза у деда плохие, но спорить я не стал, его теперь и так мало кто слушает. Я сел рядом и попросил рассказать ещё раз."},{"id":"forge_044","kind":"secret","title":"Сбережения","text":"Здесь лежат двадцать восемь серебряных на дорогу к сестре в Холлоу, и вынимать их нельзя. Я вынула два на сапоги. Потом вынула три, потому что заболел мой Гарри. Вынула ещё шесть, но лучше ему не стало. Я написала себе, что больше не вынимаю, и тут пришлось вынуть на могильный камень. Осталось четыре. Сестре я напишу, чтобы не ждала. Гарри лежит здесь, и куда я от него поеду."},{"id":"forge_045","kind":"secret","title":"Клеймо","text":"Тут лежит клеймо двора Хэдли, которое я подделал сам. Восемь лет я ставил его на свои подковы и брал за них как за настоящие. Хэдли когда-то выгнал меня из учеников и сказал, что руки у меня кривые. На прошлой неделе он показывал одну из моих подков своим ученикам и говорил им: вот как надо. Гордиться мне нечем, но очень хотелось кому-нибудь сказать. Старик, ты меня всё-таки выучил."},{"id":"forge_046","kind":"secret","title":"Запись шлаковщика","text":"Я копал отвод для шлака и пробил свод. Внизу было темно, и оттуда капало. Я опустил фонарь на верёвке и увидел мокрую черепичную крышу, а на ней лодку, привязанную к трубе хорошим узлом, как будто хозяин собирался вернуться. Дыру я заделал и никому не сказал, даже жене, хотя говорю ей всё. Шлак теперь пускаю в другую сторону, вдруг там кто-нибудь живёт."},{"id":"forge_047","kind":"secret","title":"Детский клад","text":"это мой клад. тут лежит гвоздь золотой (красил сам), заклёпка Нэда и бусина из шлака для мамы на день рожденя. кто найдёт ничево не брать. заклёпку можно"},{"id":"forge_048","kind":"secret","title":"Про хлеб","text":"По четвергам хлеб на порог вдовы Лорси кладу я. Она думает, что его приносит покойный муж, рассказывает об этом соседкам, и лицо у неё при этом такое счастливое, что я молчу. Пускай думает. Он при жизни ни разу не принёс ей хлеба."},{"id":"forge_049","kind":"secret","title":"Запрещённая песня","text":"Это песня, за которую у нас штрафуют. «Мастер сказал: ещё звено. Мастер сказал: ещё одно. Жена сказала: ужин стынет. Мастер сказал: ещё звено». Поём мы её тихо, штраф пять медяков с головы. Гаррет глухой и поёт громче всех, поэтому платит за него вся смена, и никто ни разу ему об этом не сказал."},{"id":"forge_050","kind":"secret","title":"Холодное место","text":"За третьим столбом в погребе снизу тянет холодом. Это единственное прохладное место на весь квартал, и я хожу сюда посидеть после смены, пока жена думает, что я в трактире. Пусть лучше думает так. Здесь пахнет мокрым деревом. Иногда снизу постукивают, два раза, будто монетой о доску. Я один раз постучал в ответ и больше так не делаю."},{"id":"forge_051","kind":"boss","title":"Заказ совета","text":"«Цепь, чтобы поднять мост, когда придут с юга. Сто двадцать звеньев. Мастер: принято». Ниже другой рукой: «Совета больше нет, и моста тоже». Ниже, выжжено на железе: «Звено девять тысяч сорок. Цепь пока слабая».","boss":"boss_forge","floors":[5,6]},{"id":"forge_052","kind":"boss","title":"Книга звеньев","text":"Мастер велел мне записывать. Звено сто двадцатое мы сдали, и совет заплатил. Потом мастер сказал, что у сто двадцатого есть слабое место, и мы выковали сто двадцать первое. Теперь он говорит, что слабое место у сто двадцать первого. Я спросил его, сколько ещё, ведь я обещал жене вернуться к весне. Мастер посмотрел на меня и спросил, целы ли у меня обе руки. Я ответил, что целы. Он сказал: значит, ещё.","boss":"boss_forge","floors":[5,6]},{"id":"forge_053","kind":"boss","title":"Наказ новеньким","text":"Новенькие, слушайте меня, я тут дольше всех. Звенья носите по двое, иначе в первую же неделю надорвётесь. Слово «готово» при мастере не говорите, он на него сердится, говорите «пока держит». Если он спросит, пришли ли с юга, отвечайте: нет ещё. Тогда он успокаивается и берёт молот. Когда-то он учил меня держать клещи и ночью укрывал своей курткой. Не смейтесь над ним, если хотите дожить до ужина.","boss":"boss_forge","floors":[5,6]},{"id":"forge_054","kind":"boss","title":"Записка жены","text":"Старый мой, ужин третий день стоит на столе. Я грею его о стену, она теперь горячая, как печка. Совет разошёлся, и моста больше нет, я сама ходила смотреть, там просто течёт река. Вечером к нам приедут дети с внуками. Посиди с ними хоть один вечер, я прошу тебя, они уже не помнят твоего голоса. Молот можешь взять с собой.","boss":"boss_forge","floors":[5,6]},{"id":"forge_055","kind":"boss","title":"Извещение","text":"Мастеру цеха. Извещаю вас, что заказ исполнен и закрыт, совет распущен, а печать сдана. Прошу вас расписаться в получении. Это моё пятое извещение. Предыдущие четыре вернулись ко мне с числом звеньев, написанным поверх текста, и я вынужден подшивать их как переписку. Мы же с вами вместе учились считать. Распишитесь, пожалуйста, и заходите ко мне на пиво, как раньше.","boss":"boss_forge","floors":[5,6]},{"id":"forge_056","kind":"boss","title":"Письмо с юга","text":"Мастеру от Корвина из южных деревень. Пишу вам, потому что вчера мы с вами не договорили. Мне сказали, что вы куёте цепь от нас. Никто к вам не шёл, добрый человек: в тот год у нас случился неурожай, и все разошлись по домам. Я привёз вам пять банок грушевого варенья в знак мира, его варила моя жена. Вы спросили, сколько нас. Я ответил, что я один. Вы сказали: это пока.","boss":"boss_forge","floors":[5,6]},{"id":"forge_057","kind":"boss","title":"Письмо ученика","text":"Мастер, я ушёл ночью, а ключ оставил на гвозде. Двадцать лет я про себя звал вас отцом, поэтому не смог сказать вам это в лицо. Вы учили меня, что вещь готова, когда её можно отдать кому-то в руки. Эту цепь отдать некому. Я забрал только маленький молоток, которым вы делали дочке крючки для платья. Он давно лежал без дела, и мне он как раз по руке.","boss":"boss_forge","floors":[5,6]},{"id":"forge_058","kind":"boss","title":"Письмо дочери","text":"Папа, мне уже шестьдесят один год. Я принесла тебе новый фартук, потому что прежний на тебе сгорел. Ты меня не узнал и спросил, из какой я деревни на юге. Я сказала, что с нашей улицы. Ты кивнул и велел мне подержать клещи. Я подержала, и ты обрадовался так, как радовался, когда я была маленькой. Оставляю эту записку на наковальне, вдруг ты вспомнишь, что умеешь читать. Приду ещё в четверг.","boss":"boss_forge","floors":[5,6]},{"id":"halls_001","kind":"note","title":"Жалоба ректору","chain":"bell","part":1,"text":"Господин ректор! Магистр Рен продолжает уверять за обедом, что под полом нижней палаты по большим праздникам звонит какой-то другой колокол. Это эхо нашего собственного, о чём я писал ещё в трактате. Мы с этим упрямым ослом сидим за одним столом двадцать шесть лет, я знаю все его глупости наизусть и успел к ним привязаться, но эту прошу запретить, особенно при студентах и особенно за супом. Доктор Холт."},{"id":"halls_002","kind":"note","title":"Ответ магистра","chain":"bell","part":2,"text":"Господин ректор, наш колокол треснул ещё при прошлом мэре и звучит как ведро. А тот, что слышно снизу, звучит чисто и начинает раньше нашего. Эхо, насколько мне известно, вперёд звука не забегает. Доктор Холт спускался в подвал последний раз в день получения степени, и то за вином. Передайте ему, пожалуйста, что он глух как пень и что моя жена ждёт его в воскресенье к гусю, как всегда. Магистр Рен."},{"id":"halls_003","kind":"note","title":"Записка доктора","chain":"bell","part":3,"text":"Рен, старый ты осёл, я спустился в нижнюю палату с двумя студентами и лампой, чтобы опровергнуть тебя при свидетелях. В час большого звона я приложил ухо к полу, и студенты подтвердят, что я простоял так до самого вечера. Опровержение пока откладываю. Ты забыл там свой шарф. Он мокрый, хотя пол сухой, и мне это не нравится. Надень другой, а то опять сляжешь, и с кем я тогда буду спорить?"},{"id":"halls_004","kind":"note","title":"Объявление","chain":"bell","part":4,"text":"Лекции доктора Холта и магистра Рена отменяются до окончания спора. Оба спустятся через люк под нижней палатой лично и вместе, по верёвке, поскольку ни один из них не верит другому на слово. Проигравший до конца жизни будет мыть чернильницы победителя. Ключ от кафедры я оставил у сторожа. Студентов прошу не занимать их стулья: спор закончится к четвергу. Ректор."},{"id":"halls_005","kind":"note","title":"Записка сторожа","chain":"bell","part":5,"text":"Господин ректор, я третью зиму храню ключ от кафедры, как мы договаривались. Чернильницы на обоих столах высохли, но мыть их я не стал, вдруг это повлияет на результат. В дни большого звона снизу теперь слышно ещё и стук, будто двое спорят и перебивают друг друга. Прошу выдать новую верёвку, у старой нижние шесть саженей всё время мокрые. Супруга магистра Рена по-прежнему жарит по воскресеньям гуся и спрашивает меня, не слышно ли чего. Я не знаю, что ей отвечать."},{"id":"halls_006","kind":"note","title":"Прошение","chain":"step","part":1,"text":"В канцелярию. Третья ступень парадной лестницы шатается уже шестой год. На прошлой неделе мой муж Гарольд упал с неё и сломал ногу, а шёл он к вам как раз с жалобой на эту самую ступень. Я сорок лет прошу его смотреть под ноги, и сорок лет он отвечает, что смотрит. Теперь он лежит дома и злится, а мне его жалко. Прошу починить. Милдред Оукс, Кожевенная улица."},{"id":"halls_007","kind":"note","title":"Ответ канцелярии","chain":"step","part":2,"text":"Госпоже Оукс. Лестницами у нас ведает Палата Входов, а ступенями Палата Мощения, поскольку ступень есть поднятая мостовая. Просим указать, какая именно ступень третья, считая снизу и считая сверху, и приложить справку о ноге. Пошлина за справку составляет две монеты. От себя добавлю, сударыня, что мне очень жаль вашего мужа. Постарайтесь уместить следующее прошение на одном листе, так вам выйдет дешевле. Младший писарь Симон."},{"id":"halls_008","kind":"note","title":"Прошение второе","chain":"step","part":3,"text":"В Палату Мощения. Речь идёт о третьей ступени снизу, она же девятая сверху, она же та, возле которой всегда стоит лужа. Справку о ноге прилагаю. Нога у мужа срослась криво, а справку на кривую ногу лекарь пишет отдельно, за три монеты, которых у нас нет. Гарольд ворчит, что я зря хлопочу, а сам каждый день спрашивает, нет ли ответа. В корзине лежит пирог для писаря Симона, который в прошлый раз был со мной вежлив. Милдред Оукс."},{"id":"halls_009","kind":"note","title":"Извещение","chain":"step","part":4,"text":"Госпоже Оукс. Прошение ваше удовлетворено, ступень будет починена весной. Извещаем также, что ваш супруг замечен на площади среди прочих горожан. Он стоит хорошо, на обеих ногах, и костыли ему больше не нужны. Просим забрать их из гардероба, они мешают. Приписка от руки: сударыня, пирог был очень вкусный, и мне жаль. Не ходите на площадь его звать. Я вчера пробовал, он не оборачивается. Симон."},{"id":"halls_010","kind":"note","title":"Письмо домой","chain":"percy","part":1,"text":"Дорогая матушка! Книга по риторике стоит шесть монет, и без неё меня отчислят. Пришлите шесть, а лучше семь. Я очень скучаю по вашим блинам и ем здесь одну репу, так и передайте отцу. Вчера у шляпника Пинчера я видел шляпу точь-в-точь как у отца, только зелёную. Это к делу не относится. Целую ваши руки, не болейте и не таскайте воду сами. Ваш любящий сын Перси."},{"id":"halls_011","kind":"note","title":"Письмо домой","chain":"percy","part":2,"text":"Дорогая матушка! Книгу я купил, спасибо. Она зелёная, с полями и очень мне идёт. Денег пока больше не присылайте, у нас творится странное: снег не лежит, печи никто не топит, в спальне жарко, и все сидят с открытыми окнами. Лекции пока идут. Доктор Брэдли уверяет, что это к хорошей погоде, но выглядит он нездорово. Вы писали, что отец кашляет, пусть пьёт горячее. Я приеду, как только просохнут дороги, и признаюсь вам кое в чём насчёт книги."},{"id":"halls_012","kind":"note","title":"Письмо ректора","chain":"percy","part":3,"text":"Сударыня! С прискорбием сообщаю, что студент Перси Вуд отчислен за пропуски. С первого снега он не был ни на одном занятии. С утра он стоит на площади вместе с прочими и на все вопросы отвечает, что ему хорошо. Я сам подошёл к нему и протянул ваше письмо, но он его не взял. Шляпу, зелёную, он оставил в спальне. Можете забрать её у привратника в любой день, кроме среды. Мальчик он был способный и очень ею гордился."},{"id":"halls_013","kind":"note","title":"Табличка","text":"Просьбы принимаются по вторникам, жалобы по средам. Жалобы на то, что просьбы принимаются по вторникам, не принимаются. Обращайтесь к младшему писарю, старший болеет с весны. Мать младшего писаря просит на него не кричать."},{"id":"halls_014","kind":"note","title":"Протокол","text":"Первым вопросом совет рассмотрел ремонт моста и отложил его. Вторым вопросом совет выяснял, кто съел пирог, принесённый к первому вопросу. Прения заняли четыре часа. Постановили образовать комиссию по пирогу, председателем назначили советника Тибальда, а его мантию с крошками приобщили к делу. Председатель просил записать, что пирог был с капустой, как у его покойной матушки, и что больше он ничего не скажет."},{"id":"halls_015","kind":"note","title":"Налог на окна","text":"Кожевенная улица. Реннер платит за шесть окон шесть монет, Хэтч за три окна три монеты. Фиддл заложил кирпичом пять окон из шести и платит одну монету. Жена Фиддла подала жалобу на Фиддла, потому что в доме стало темно и она не видит, что вяжет. Жалобу мы приняли, пошлина две монеты. Фиддл заплатил пошлину за жену сам и сказал, что так всё равно дешевле."},{"id":"halls_016","kind":"note","title":"Упражнение","text":"Логика, задача четвёртая. Если Тибальд берёт взятки, Тибальд покупает лошадь. Тибальд купил лошадь. Следует ли из этого, что Тибальд берёт взятки? Ответ ученика: да. Учитель написал чернилами: «Неверно, зачеркни и перепиши». Ниже тот же учитель спросил карандашом: «А какой масти лошадь, ты сам её видел?»"},{"id":"halls_017","kind":"note","title":"Ученику писаря","text":"Перо чини от себя, а чернила на ночь закрывай. Если проситель плачет, дай ему сесть, только не на стул с целой ножкой, он у нас один и стоит для советника. Слово «немедленно» в наших бумагах означает «весной». По пятницам подметаешь ты. Твоя мать просила меня следить, чтобы ты ел, так что обедаешь ты теперь в полдень, и это приказ."},{"id":"halls_018","kind":"note","title":"Записка","text":"Хильда, я нашёл в архиве дело твоего деда, того самого, что украл гуся. Теперь оно закрыто в его пользу, потому что сегодня после обеда я сам его закрыл. Приходи в среду к полке с соляными податями, там никто не бывает. Там немного дует, так что надень что-нибудь тёплое. Мне очень хочется увидеть, как ты будешь смеяться. Твой Оливер."},{"id":"halls_019","kind":"note","title":"Молитва","text":"Святая Ида Чернильная, сделай так, чтобы на экзамене меня спросили про реки. Рек я выучил две. Если про реки нельзя, пусть заболеет доктор Холт, только не сильно и на один день. Мать продала козу, чтобы я мог здесь учиться, и я не могу вернуться домой и сказать ей, что провалился. Обещаю поставить свечу, как только у меня появятся деньги."},{"id":"halls_020","kind":"note","title":"Счёт трактира","text":"Трактир «Перо и кружка», счёт за месяц. Кафедра риторики выпила четырнадцать кружек. Кафедра логики выпила девять и разбила окно. Кафедра богословия выпила две и просила никому не говорить. Кафедра счисления итог оспаривает. Доктор Холт и магистр Рен снова ругались, кто за кого платит, и в конце концов оба заплатили за обоих. Я не стал их поправлять."},{"id":"halls_021","kind":"note","title":"Эпитафия","text":"Списано с надгробия для книги совета. «Здесь покоится Бертрам Флэкс, сорок лет секретарь совета. Слушали. Постановили». Ниже кривыми буквами кто-то нацарапал гвоздём: «Он хорошо пел. Каменщику за эту строчку мне заплатить было нечем, и я написала её сама. Берти, мне без тебя очень тихо»."},{"id":"halls_022","kind":"note","title":"Акт порчи","text":"Мыши съели все дела на букву Г, целиком. Граждане на букву Г временно считаются незарегистрированными и налогов не платят. С понедельника мы получили двенадцать прошений о перемене фамилии на Гудмен. Прошения принимаются за одну монету, очередь стоит вдоль левой стены. Первой в очереди стоит моя тёща, и она впервые за девять лет мне улыбнулась."},{"id":"halls_023","kind":"note","title":"Опись редкостей","text":"Опись за год. У нас хранится сушёная рыба с ногами, одна штука. Хранится череп, и ни одна кафедра не признаёт его своим. Есть ящик с надписью «не для ректора», я его не вскрывал. Есть левая перчатка, всегда тёплая, и при каждой описи она лежит на другом столе. Прошу вынести перчатку из описи, она портит мне отчётность. Сторож говорит, что она просто ищет вторую, и теперь мне её жалко."},{"id":"halls_024","kind":"note","title":"Шпаргалка","text":"Королей звали Эдмунд Первый, Эдмунд Второй и Эдмунд Хромой, который, кажется, и есть Второй. Налог на дым ввели при ком-то из них. Если спросят дату, надо закашляться. Не забыть спросить у Перси, что такое десятина, и вернуть ему перо. И написать маме, что я жив, а то она опять приедет и будет при всех поправлять мне воротник."},{"id":"halls_025","kind":"note","title":"Правила читальни","text":"Прошу не слюнить страницы и держать свечу на блюдце. С трактатом о ядах работайте в перчатках, с трактатом о подвалах не работайте вовсе. Профессор Фабиан спит в третьем ряду со дня открытия. Не будите его, пока мы не решим, кому это поручить. Каждую осень дочь приходит укрыть его новым пледом и просит вас не шуметь."},{"id":"halls_026","kind":"note","title":"Квитанция","text":"Получен от мясника Гранта один окорок на нужды комиссии по проверке весов. Комиссия состоит из меня одного. Весы признаны верными, окорок тоже. Половину окорока комиссия отправила своей матери, которая жалуется, что комиссия ей не пишет. Д. Ларкин, сборщик."},{"id":"halls_027","kind":"note","title":"Объявление секретаря","text":"Кто взял большую печать, верните её, пожалуйста. Всё, что скреплено малой печатью с прошлого четверга, считается скреплённым большой. Малая печать тоже пропала, и пока мы пользуемся пуговицей. Из-за этой путаницы вдова Крэм третий день числится замужем за Хейзом. Просим не беспокоить по этому поводу её и особенно Хейза: он двадцать лет не решался с ней заговорить и теперь боится, что бумагу исправят."},{"id":"halls_028","kind":"note","title":"Выдача дров","text":"Первая неделя после сбора яблок, поставка последняя. На Кожевенную мы выдаём по вязанке на дом, а где есть больной, по две. Школе не досталось ничего, детям велено приходить в отцовских куртках. Совету ушло шесть возов, в подвал, под замок. На полях чужой рукой: «Лоренс, куда делся седьмой воз? Моя мать третий день жжёт стулья, а я думал, что мы с тобой друзья»."},{"id":"halls_029","kind":"note","title":"Записка жене","text":"Гвен, к ужину меня не жди, я стою в очереди у весовой. Говорят, у ворот снова раздают муку, хотя я уже не знаю, кто её раздаёт. Если к темноте не вернусь, возьми с полки чёрную кружку, в ней лежит расписка, и сходи к Винсенту, он должен нам с лета. На ночь закрой дверь на оба засова и дров не жалей, потом разберёмся. Поцелуй за меня Дэйви и не сиди у окна, я постараюсь вернуться скоро."},{"id":"halls_030","kind":"note","title":"Сочинение","text":"Моя зима. зимой холодно а этой зимой тепло. у нас сняли двери патамушта незачем. папа сказал пишы что хочеш толко про ворота непиши. я непишу про ворота. мы отпустили собаку она ушла туда и не вернулась но она взрослая. я каждый вечер оставляю ей кость на пароге."},{"id":"halls_031","kind":"note","title":"Замеры снега","text":"Тимоти, проверьте, пожалуйста, мою линейку. В первый день снег у ратуши лежал по локоть. На второй день у ратуши стало сыро, а за стеной снега было по колено. На третий день площадь совсем высохла, а часовые говорят, что снаружи намело по грудь и край снега идёт вдоль стены ровно, будто его отрезали ножом. Я двадцать лет измеряю снег и никогда ни о чём вас не просил. Зайдите ко мне вечером, мне страшно."},{"id":"halls_032","kind":"note","title":"На полях","text":"Автор дурак. Ниже, другими чернилами: Сам дурак, автор это я. Ниже, третьей рукой: Автор умер в прошлом веке. Снова второй рукой: Знаю. Я сам удивился."},{"id":"halls_033","kind":"note","title":"Письмо сыну","text":"Симон, сынок, передаю с Бетт пирог и чистые манжеты. Писарь в грязных манжетах никогда не выйдет в секретари, вот и отец твой не вышел, хотя человек был хороший. Твой кашель слышно через всю площадь, и люди спрашивают меня, чей это. Я отвечаю, что мой. Попроси кого-нибудь посмотреть твою печь, она у тебя дымит, а ты и не замечаешь. Ешь горячее и пиши матери хоть раз в неделю, я уже забываю твой почерк."},{"id":"halls_034","kind":"note","title":"Приютская книга","text":"Девочка лет семи, найдена у ворот в первый снег. Назвать своё имя не может. На вопрос, как её зовут, отвечает «потом», потому что так ей сказала мать, уходя. Записана в приютскую книгу как Потом Воротная. Ест хорошо. Каждый вечер она садится у окна лицом к воротам, и я сажусь рядом с шитьём, чтобы ей не было одиноко. Сестра Агнес."},{"id":"halls_035","kind":"note","title":"Преемнику","text":"Шкаф слева не закрывается, а шкаф справа не открывается. Вдова Кэрью приходит по пятницам, дела у неё давно нет, поэтому не спорь с ней и дай ей сесть. Мёд в третьем ящике оставляю тебе. В четвёртый не заглядывай, там лежит мой обед с прошлой осени. Береги спину и уходи домой вовремя: я просидел здесь тридцать лет, и за это мне никто спасибо не сказал. Вдова Кэрью, правда, сказала, так что ты с ней поласковей."},{"id":"halls_036","kind":"note","title":"Анекдот","text":"Вчера в трактире рассказали про сборщика податей. Умер он, пришёл к вратам и спрашивает: «Куда мне, вверх или вниз?» Ему говорят: «Как совесть подскажет». Он задумался и спрашивает: «А где дешевле?» Смеялись все, кроме сборщика Ларкина, он записывал, кто смеялся. Его мать как раз принесла ему обед и смеялась громче всех, её он записал первой."},{"id":"halls_037","kind":"note","title":"Дневник переписчика","text":"Сегодня я переписывал четвёртый том венчаний и нашёл свадьбу своих родителей. У тогдашнего писаря был плохой почерк, и мать он записал как Эдит, а она всю жизнь была Эдна. Я исправил. Потом я долго сидел над этой страницей, потому что отец расписался там так старательно, будто сдавал экзамен. Лёг поздно, свечу списал на канцелярию."},{"id":"halls_038","kind":"note","title":"Расписание стражи","text":"Ночная стража у ворот. Понедельник: Нед. Вторник: Нед. Среда: Нед, потому что Тобиас занят. Четверг: Нед просит его заменить, потому что ночью кто-то снаружи спрашивает его, не холодно ли ему. Пятница: Нед, замены мы не нашли. Выдать Неду шарф. Приходила его мать, спрашивала, почему всё время он, и я сказал ей, что Нед у нас лучший. Она ушла довольная. Прости меня, Нед."},{"id":"halls_039","kind":"note","title":"Табличка","text":"Казначейство закрыто на сверку и откроется, когда всё сойдётся. Суп ставьте у двери, миску заберёте утром, она будет пустая и чистая. Просьба не стучать, он сбивается. Ниже приписано другой рукой: «Генри, ты считаешь уже четвёртый год. Пусть не сходится, выходи, я соскучилась»."},{"id":"halls_040","kind":"note","title":"Афиша лекции","text":"В четверг в большой палате доктор Брэдли прочтёт лекцию «О природе тепла и её благодетельных последствиях». Шубы сдавать в гардероб не нужно, шубы в этом году вообще никому не нужны. Лекция «О природе холода» отменена, потому что лектор не отвечает на наши запросы. Его сестра просит всех, кто его видел, зайти к ней на Хлебную улицу."},{"id":"halls_041","kind":"secret","title":"Книга очагов","text":"Старик, который смотрит за костром на площади. Подать за очаг мы с него не берём, потому что он значится в этой книге и при моём деде, и при деде моего деда, всякий раз в одной и той же графе. Откуда он прибыл, он не сказал. Когда я пришёл его записывать, он спросил, почему писарь так долго, и налил мне чаю с мёдом. Он сказал, что мой дед любил именно с мёдом, и это правда."},{"id":"halls_042","kind":"secret","title":"Статья устава","text":"Устав совета, статья без номера. Если город падёт, огонь с площади надлежит вынести наверх прежде казны. Тот, кто принял ведро с углями, уходит и не оглядывается, даже если здесь остаются его родные. Кому идти, решает старик у костра. Совет на этот счёт не совещается и протокола не ведёт. На полях карандашом: «Я переписал это и весь вечер просидел у матери, ничего ей не объясняя»."},{"id":"halls_043","kind":"secret","title":"План города","text":"Ректору не показывать. Я купил у старьёвщика план города, очень старый. Площадь на нём находится на нашем месте, и костёр отмечен там же, а на Хлебной улице нарисованы канал и пристань. Никакого канала у нас нет. Возчик Гарт говорит, что в его подвале весной пахнет тиной и что он давно привык. Покажу план брату: он смеётся над всем, что я покупаю, но тут, пожалуй, смеяться не станет."},{"id":"halls_044","kind":"secret","title":"Настоящий подсчёт","text":"Пишу для себя. Чёрных камешков было двести шесть, белых триста сорок, и за белыми люди ходили на реку, раз на рынке их не оказалось. Совет велел записать наоборот, потому что сын угольщика обходится городу дешевле. Мне приказано сжечь эту бумагу, но бумага нынче дорога. А ещё я видел, как моя старая соседка Нэн шла на реку пешком, по морозу, с больными ногами, за одним белым камешком. Пусть это хоть где-то будет записано."},{"id":"halls_045","kind":"secret","title":"Дровяной список","text":"Вот кому в последнюю зиму я приписал дров по поддельной бумаге: вдове Кэрью две вязанки, детям Арденов четыре, слепому Нату три. Если это найдёт ревизор, прошу учесть, что почерк у меня красивый и что я раскаиваюсь, только не сейчас. Слепому Нату я сказал, что дрова от совета. Он рассмеялся, похлопал меня по щеке и велел беречь себя."},{"id":"halls_046","kind":"secret","title":"Признание","text":"Степень я получил за трактат, который переписал у покойного. Покойного звали Хью, он был мой брат и писал лучше всех, кого я знал, а я умел разговаривать с ректором. При жизни он отдавал мне всё, что у него было, и я решил, что он не обидится. Я и теперь так думаю, только по ночам хуже. Если кто-нибудь это найдёт, прошу поставить его имя на книге. Она стоит на пятой полке, кажется. В тот ряд я давно не захожу."},{"id":"halls_047","kind":"secret","title":"Устав братства","text":"Устав Братства Подвальной Свечи. Наша цель: узнать, что находится внизу. Собираемся по четвергам. Нас трое, взнос составляет одну свечу. Последнее собрание не состоялось: Бен боится, Клара боится, я тоже боюсь, но я секретарь и обязан это записать. Следующее собрание проведём у Клары, её мама печёт яблочный пирог, и там совсем не страшно."},{"id":"halls_048","kind":"secret","title":"Смета","text":"Каменщики просят доплаты: на дне котлована под ратушу им попалась чужая крыша, целая, с трубой. Совет заплатил, велел считать крышу фундаментом и в бумагах больше не упоминать. Черепица оказалась хорошая, её забрали на кухню. Записываю уже не для сметы: старый Уилл снял шапку, прежде чем класть на эту крышу первый камень, и велел снять остальным. Мастер его обругал, а потом снял и сам."},{"id":"halls_049","kind":"secret","title":"Письмо матери","text":"Сынок, я понимаю, что тебе теперь некогда. Помнишь воробьёв, которых ты зимой приносил домой в шапке? Отец ругался, а ты клал их к печке и ревел, если какой не отогревался. Мне передали, что ты плохо спишь. Поешь чего-нибудь горячего, ради меня. В городе теперь тепло, все говорят, что это ты, а я всё равно мёрзну. Зайди ко мне, когда сможешь. Я не буду ни о чём спрашивать."},{"id":"halls_050","kind":"secret","title":"За шкафом","text":"За шкафом я нашёл листок, очень старый, на незнакомом письме. Прочесть его я не смог, но кто-то нарисовал там домик с дымком. Я положил его обратно и рядом оставил вот этот. Рисую тоже: домик, дымок и ещё собаку, у нас есть собака, её зовут Пуговка. Дочка подрисовала солнце и велела сказать тебе, кто бы ты ни был, что у нас тут хорошо. Если найдёшь, добавь своё."},{"id":"halls_051","kind":"boss","title":"Хроника","chain":"mayor","part":5,"boss":"boss","floors":[1,8],"text":"Ключи от ворот ему вручили в ночь первого снега. К утру в городе стало теплее, и люди вышли благодарить мэра на площадь. У мэра было хорошее лицо, а тень от него ложилась к костру."},{"id":"halls_052","kind":"boss","title":"Предвыборный листок","chain":"mayor","part":1,"boss":"boss","floors":[1,8],"text":"Горожане! В мэры идёт сын угольщика. Четыре зимы он развозил дрова вдовам и денег с них не брал, и многие из вас сами видели его на своём пороге. Он говорит, что больше в этом городе никто не замёрзнет, а мать его подтверждает, что слов на ветер он не бросает. Голосуем в четверг у рыночных весов: чёрный камешек за него, белый против. Белых камешков на рынке сейчас нет, мы выясняем почему."},{"id":"halls_053","kind":"boss","title":"Письмо сестре","chain":"mayor","part":2,"boss":"boss","floors":[1,8],"text":"Мэрион, дрова подорожали втрое, обозов нет с самого сбора яблок. Новый мэр сам принёс старой Иде вязанку и сел чистить ей печь, представляешь? А вечерами он ходит к воротам и подолгу там стоит, и стражники говорят, что он с кем-то разговаривает. Привези шерсти, если доедешь, Робину совсем не в чем ходить. А лучше просто доедь, сестрёнка. Мне без тебя здесь неспокойно."},{"id":"halls_054","kind":"boss","title":"Постановление","chain":"mayor","part":3,"boss":"boss","floors":[1,8],"text":"Совет постановил: ввиду нехватки дров и болезни привратника передать ключи от ворот господину мэру, чтобы он мог принять обоз, когда обоз придёт. Вручить их в первый снег, как велит обычай. Шесть советников проголосовали за. Советник Тибальд проголосовал против и просил записать, что обоза никто не видел и что привратник, его друг с детства, вчера вечером был совершенно здоров. Записано."},{"id":"halls_055","kind":"boss","title":"Расписка привратника","chain":"mayor","part":4,"boss":"boss","floors":[1,8],"text":"Я, Вальтер Кросс, привратник, сдал господину мэру два ключа, большой и от калитки, которые носил сорок один год. На обороте, уже дома: Марта, ты спала, и я не стал тебя будить. Господин мэр расписался и спросил, слышу ли я, как снаружи дышат. Я сказал, что туговат на ухо. Он сказал, что это хорошо, и велел идти домой спать. Я слышал, Марта. Шёл снег, первый в этом году. Я лёг не раздеваясь, а ты утром, прошу тебя, не открывай дверь."},{"id":"halls_056","kind":"boss","title":"Указ","boss":"boss","floors":[1,8],"text":"Указ господина мэра. Налог на дрова отменяется за ненадобностью. Трубочистам выдать жалованье вперёд и распустить. Горожанам разрешается не носить шапок. На обороте записка для писаря: подпись опять прожгла лист, закажи бумагу потолще и не жалуйся на запах. Писарь отправил эту копию домой и приписал снизу: «Мама, шапку всё равно носи»."},{"id":"halls_057","kind":"boss","title":"Письмо дяде","boss":"boss","floors":[1,8],"text":"Дядюшка Кларенс, приезжайте к нам, шубу можете не брать. Всю зиму у нас тепло, снег не лежит, на улицах даже ночью можно спать, и дети спят, им нравится. Вороны улетели, а так всё хорошо. Мэр говорит, что ворота теперь открыты для всех, и спрашивал про вас, он вообще про всех спрашивает. Вы давно не видели маленькую Лотти. Она теперь совсем не плачет и не просит есть. Приезжайте и тётю привозите, мы все по вам соскучились."},{"id":"halls_058","kind":"boss","title":"Счёт живописца","boss":"boss","floors":[1,8],"text":"За парадный портрет господина мэра двенадцать монет. За второй холст ещё две, потому что первый покоробился, пока господин мэр стоял рядом. За вторую коробку охры три монеты. Лицо получилось хорошее, заказчик доволен. На обороте этой копии: Бесс, получи деньги по счёту и собирай детей. В ратуше я сказал, что уезжаю к сестре, а сестры у меня, как ты знаешь, нет. Я жду вас на мельнице у Хэтчей. Вещей много не бери."},{"id":"halls_059","kind":"boss","title":"Детской рукой","boss":"boss","floors":[1,8],"text":"мэр падарил мне прянек. он был горячий. мама сказала ешь и скажи спасибо. я сказал спасибо. он сказал пажалуста а рот неоткрывал. я спрятал прянек под кравать он там до сих пор горячий. мне страшна но маме я неговарю а то она тоже забоица."},{"id":"halls_060","kind":"boss","title":"Прошение в совет","boss":"boss","floors":[1,8],"text":"Просим вернуть ключи от ворот привратнику Вальтеру. Мы знаем его всю жизнь, и он ни разу нас не подвёл. Подписи: Хьюберт, сапожник. Мод Арден, вдова. Ниже кто-то дописал ровным почерком: Хьюберт отзывает подпись и благодарит за заботу. Мод Арден отзывает подпись и благодарит за заботу."},{"id":"magma_001","kind":"note","title":"Законы","text":"Закон первый: чужое не брать. Закон второй: что чужое, скажет Орин. Если вам понадобится третий закон, приходите к Орину днём. Вечером он устаёт и путает чужое со своим, это я вам говорю как его жена."},{"id":"magma_002","kind":"note","title":"Решение схода","text":"Сегодня решили ставить стену. От кого мы будем ею отгораживаться, решим, когда достроим. Камень носят все, кто ходит на двух ногах. Дункан сказал, что у него болит спина, и я так и записал: Дункан, спина. Вчера эта спина несла домой целого барана, но я ему друг и про барана писать не стану.","chain":"stena_dunkana","part":1},{"id":"magma_003","kind":"note","title":"Закон о воде","text":"Воду для питья берите выше всех по ручью. Мойтесь ниже, а скотину поите ещё ниже. Тот, кто живёт ниже всех, сам выбрал, где сесть, и извиняться перед ним никто не будет. Рольф, это про тебя. Мы тебя всё равно любим, но пить из ручья у своего дома я тебе не советую."},{"id":"magma_004","kind":"note","title":"Надпись у двери","text":"Это дверь, первая у нас. Сначала стучите рукой, а потом ждите, пока я скажу входить. Кто войдёт по-старому, получит ковшом. Муж мой тоже получит, он уже получал. Эдна."},{"id":"magma_005","kind":"note","title":"Первая расписка","text":"Я, Берт, взял у Иды козу на один день, потому что младшему нужно молоко. Завтра я её верну. Ида велела нацарапать это на глине, она говорит, что так надёжнее, чем помнить. Ида, мы с тобой шли сюда рядом сорок дней, и мне обидно. Но за козу спасибо.","chain":"pervyi_dolg","part":1},{"id":"magma_006","kind":"note","title":"Запись схода","text":"Вчера весь вечер собирались назвать место, где мы живём. Одни предложили Здесь, другие Тут, третьи У Трещины. Гарт предложил Дом Гарта, но жена посмотрела на него, и он сел. До темноты мы так и не решили. На глине пока пишем Здесь."},{"id":"magma_007","kind":"note","title":"Распоряжение","text":"Гартов у нас двое, и это путает людей. С этой луны высокий будет зваться Длинный Гарт, а второй Другой Гарт. Другой Гарт просил записать, что он против. Я записал. Не дуйся, Гарт, никакой ты нам не другой."},{"id":"magma_008","kind":"note","title":"Ночь при огне","text":"Сегодня моя первая ночь при огне. Хэмиш велел мне не спать, давать щепки по одной и не ставить горшок на мокрое, а утром показать ему запись, как прошла ночь. Огонь размером с кулак и кашляет, когда ему дают сырое. Мне стало его жалко, и я сказала ему своё имя, всё равно делать нечего. Мама думает, что я боюсь темноты. Рядом с ним я не боюсь. Фрея.","chain":"nochnaya_ochered","part":1},{"id":"magma_009","kind":"note","title":"Дело об огне","text":"Тобин пришёл заявить о краже огня. Ночью Хоб взял у него уголь. Огонь у Тобина остался, и теперь у Хоба он тоже есть, поэтому мы не знаем, как судить. Тобин настаивает, что огня у него стало меньше. Они братья и всю дорогу спали спина к спине, так что мы подождём до утра, и судить, может быть, не придётся."},{"id":"magma_010","kind":"note","title":"Первый торг","text":"На шестой день всем велели нести к камню, что у них есть лишнего, чтобы меняться. Пришли шестеро. Лишнего не нашлось ни у кого. Мы постояли и поговорили про больную ногу Мод, а потом Вилл отдал ей свою палку просто так. В следующий шестой день придём ещё."},{"id":"magma_011","kind":"note","title":"Объявление школы","text":"Открылась школа. Учит Осберт, он знает двенадцать знаков. Приносите свой сланец и свой камешек. Сегодня учим «хлеб» и «нет хлеба». Это один и тот же знак, только во втором есть черта. Матери, накормите детей перед школой, а то они запомнят только второй.","chain":"shkola_na_slance","part":1},{"id":"magma_012","kind":"note","title":"Первый суд","text":"Фиск взял гуся. Судить мы не умеем, поэтому Фиск сам подсказывал, кому где встать и кто говорит первым. Решили вернуть гуся хозяйке, но гуся не нашли. Хозяйка сказала, что гусь щипал её каждое утро и что она уже скучает. Фиску велели и дальше подсказывать, когда будем судить кого-нибудь ещё."},{"id":"magma_013","kind":"note","title":"Молитва","text":"Огонь, мы дали тебе сухого, хотя сами спим на мокром. Сделай, пожалуйста, чтобы дождь кончился и чтобы у Эдны родился живой. Она двоих схоронила по дороге и больше об этом не говорит. Если это дело не к тебе, передай тому, к кому надо."},{"id":"magma_014","kind":"note","title":"Закон о тепле","text":"Тёплую сторону, где земля греет спину, делим так: первыми идут старые, потом те, у кого младенец, потом те, кто сильно просит. Кто просит сильно, определяет Орин. Орин просит сильно и говорит, что это ради жены, потому что она мёрзнет. Жена говорит, что не мёрзнет.","chain":"teplaya_storona","part":1},{"id":"magma_015","kind":"note","title":"Надгробный камень","text":"Здесь лежит Мод, первая, кого мы тут положили. Место она выбрала сама и при жизни ругала всех, кто по нему ходил. Мы и теперь обходим его стороной. Мама, не ругайся."},{"id":"magma_016","kind":"note","title":"Запись о похоронах","text":"Ульрик умер этой ночью. Раньше мы клали своих под камни и шли дальше, а теперь дальше мы не идём. Его жена спросила, где его положить, чтобы не видеть могилу из двери. Вечером она пришла снова и спросила, где положить, чтобы видеть."},{"id":"magma_017","kind":"note","title":"Обмер стены","text":"Стена пошла прямо, как велел каменщик, и дом Дункана остался с той стороны. Дом у него кривой и всем мешал, но Дункана мы любим, и никто не хочет говорить ему первым. Сейчас он гостит у сестры. Мы тянули камешки, кому объяснять, когда он вернётся, и вытянул я. Дайте мне с собой лепёшек.","chain":"stena_dunkana","part":2},{"id":"magma_018","kind":"note","title":"Записка Коре","text":"Кора, я вернусь к жатве. Пишу это, чтобы ты показала мне глину, когда я скажу, что не обещал. Корм козам я оставил у стены. Не таскай воду одна, попроси Вилла, и ложись пораньше. Я буду скучать, только никому этого не показывай. Бран."},{"id":"magma_019","kind":"note","title":"Записка Виллу","text":"Вилл, я отдала тебе свою очередь у тепла, потому что у тебя кашель. Другой причины нет, и ты ничего такого не думай. Вечером я буду у ручья. Приходи, там кашлять тоже можно. Нелл."},{"id":"magma_020","kind":"note","title":"Детской рукой","text":"я видела как камень тёк. он тёк как суп. мама сказала не ври. я сунула в него палку и палка пропала. я принесла другую палку и сказала смотри а мама всё равно говорит не ври и держит меня за руку очень крепко"},{"id":"magma_021","kind":"note","title":"Жалоба Иды","text":"Берт обещал вернуть козу завтра. С тех пор прошло сорок завтра, а коза всё ещё у него. Я хожу на неё посмотреть, она узнаёт меня и блеет, и я ухожу. Берт говорит, что коза теперь другая, потому что у неё козлёнок, а козлёнка он у меня не брал. Я знаю Берта всю жизнь и скажу прямо: я его побью.","chain":"pervyi_dolg","part":2},{"id":"magma_022","kind":"note","title":"Подпись к рисунку","text":"это наш дом. это мама. это огонь. это дядя он стоит внизу в трещине и машет мне рукой. папа сказал рисуй только то что есть. я и нарисовала что есть"},{"id":"magma_023","kind":"note","title":"Рецепт супа","text":"Дочка, суп теперь варят так. Опусти горшок на верёвке в щель, верёвку бери с запасом, посчитай до сорока и тяни. Кто считает плохо, тот ест сырое. Кто отпустит верёвку, идёт к Альде просить новый горшок, а Альда нас с тобой и так не любит, так что держи крепче."},{"id":"magma_024","kind":"note","title":"Наказ гончара","text":"Глину, сынок, мни, пока она не станет мягкая, как мочка уха. Потом суши её в тени шесть дней и только после этого ставь на жар. Если горшок треснул, значит, ты спешил, как и я в твои годы. Черепки выноси ночью, чтобы Альда не считала."},{"id":"magma_025","kind":"note","title":"Наказ писцу","text":"Глины на всех не хватает, поэтому табличка эта для ячменя, и писать на ней надо только про ячмень. Твою вчерашнюю табличку про жену я по ошибке обжёг вместе с остальными, и теперь то, что ты там написал, будет всегда. Я прочитал, сынок. Написано хорошо, только ячменя там нет ни горсти."},{"id":"magma_026","kind":"note","title":"Ночь при огне","text":"Огонь вырос! Мы переложили его в большой горшок, потому что старый треснул. Хэмиш долго ходил смотреть на черепки и вздыхал, как будто хоронил родню. Я принесла ему поесть и посидела рядом. Щепки я теперь даю по две, и огонь, по-моему, стал ко мне добрее. Фрея.","chain":"nochnaya_ochered","part":2},{"id":"magma_027","kind":"note","title":"Жалоба соседу","text":"Рольф, твоя коза съела мою крышу. Крыша была из травы, это я признаю. Теперь у меня нет крыши, у твоей козы был обед, а ты стоишь и говоришь, что коза молодая. Мы с тобой были соседями ещё тогда, когда у нас не было домов, поэтому злиться долго я не буду. Приходи завтра и неси траву, а козу привяжи."},{"id":"magma_028","kind":"note","title":"Запись о старшем","text":"Старшего мы выбирали поднятой рукой. Орин в это время чесался, и его выбрали. Потом он сказал, что отказывается, но ему велели со старшим не спорить. Жена обняла его и сказала, что рука у него всегда поднималась не вовремя."},{"id":"magma_029","kind":"note","title":"Упражнение","text":"хлеп хлеп хлеп хлеп хлеп хлеп. осберт сказал напиши ещё пять раз. у меня камешек стёрся. хлеп. можно я нарисую собаку. она у нас хорошая и тоже любит хлеп","chain":"shkola_na_slance","part":2},{"id":"magma_030","kind":"note","title":"Перепись к зиме","text":"Мы пересчитали всех на зиму, и нас сорок один. С младенцем Эдны будет сорок два, но он родился только этой ночью и ещё очень маленький. Я пишу сорок один, а рядом оставляю место. Эдна, весной я допишу его сам, обещаю."},{"id":"magma_031","kind":"note","title":"Знак у тропы","text":"Здесь идёт дорога. Дальше дороги нет, потому что мы устали. Кто пойдёт дальше, пусть утаптывает сам. А если ты тоже устал, возвращайся к нам, у нас есть суп."},{"id":"magma_032","kind":"note","title":"Жалоба сторон","text":"Жители тёплой стороны жалуются, что у них воняет тухлым яйцом и плавятся подошвы. Жители холодной стороны жалуются, что у них дует и что им завидно. Старший велел им поменяться на неделю, и они поменялись. Теперь обе стороны говорят, что на той было лучше, и ходят друг к другу в гости, чтобы это сказать.","chain":"teplaya_storona","part":2},{"id":"magma_033","kind":"note","title":"Решение о знаках","text":"Мы договорились о знаках для камня, воды, ячменя и долга. Гвен просит придумать ещё знак для «извини». Рольф сказал, что до сих пор мы без него обходились. Тогда его жена спросила с лавки, кто это мы. Решение отложили."},{"id":"magma_034","kind":"note","title":"Дни на сланце","text":"Я царапаю на сланце дни с тех пор, как мы пришли. Бет говорит, что один день я нацарапал дважды, тот, когда она рожала. Исправлять я не стал, тот день и был за два."},{"id":"magma_035","kind":"note","title":"Письмо Дункана","text":"Вы заложили мне вид. Я теперь живу снаружи, один, и это, как я понял, называется другая страна. Воду из моего ручья вы берёте? Берёте. Поэтому с каждого ведра вы должны мне одну лепёшку. И передайте Дэви, что я всё ещё считаю его другом, пусть приходит, только тоже с лепёшкой. Дункан, хозяин всего, что за стеной.","chain":"stena_dunkana","part":3},{"id":"magma_036","kind":"note","title":"Долговая глина","text":"Я, Тобин, должен Гвен одну пощёчину. Она сама велела это записать, потому что сейчас у неё руки в тесте. Гвен, я знаю, за что, и я виноват. Щёку принесу, когда скажешь."},{"id":"magma_037","kind":"note","title":"Счёт Рэна","text":"Счёт за ячменную воду. Тобин выпил шесть кружек, Хоб пять, а Орин две и говорит, что одну. Прошу заплатить сегодня, пока вы все помните, что было вкусно. Вчера Тобин и Хоб пели про маму и плакали, и за это я с них ничего не беру. Рэн."},{"id":"magma_038","kind":"note","title":"Решение старшего","text":"Старший рассудил, что коза принадлежит Иде, а козлёнок им обоим пополам. Как это пополам, он сказать отказался. Ида предлагает держать козлёнка у себя по очереди, неделю она, неделю Берт. Знаков для этого не хватило, поэтому дальше они нарисовали сами, и Берт на рисунке Иды вышел с рогами.","chain":"pervyi_dolg","part":3},{"id":"magma_039","kind":"note","title":"Наказ ученику","text":"Шов над швом не клади, клади поперёк. Углы ставь первыми. Когда положишь верхний ряд, сядь рядом и посиди. Если стена молчит, значит, всё хорошо, иди ужинать. Если заскрипит, зови меня и не бойся, сынок, я и сам в твои годы ронял стены."},{"id":"magma_040","kind":"note","title":"Знак у трещины","text":"У трещины не играть. Детям нельзя, собакам нельзя и Гарту нельзя, ему уже пятьдесят. Это писала его мать, и она всё видит."},{"id":"magma_041","kind":"note","title":"Где ночует огонь","text":"Сегодня огонь ночует у Гвен, завтра у Хоба, а потом у Другого Гарта. У Тобина он ночевать не будет, пока Тобин не извинится. Перед Гвен или перед огнём, пусть выберет сам. Мы все надеемся, что перед Гвен."},{"id":"magma_042","kind":"note","title":"Жалоба на пепел","text":"Опять пепел на белье, третий раз за эту луну, а я стирала его утром у ручья. Жаловаться на это некому, поэтому я пишу и кладу глину на камень. Мой покойный муж сказал бы, что надо было вешать с другой стороны, и был бы неправ. Я бы дорого дала, чтобы он это сказал. Альда."},{"id":"magma_043","kind":"note","title":"Ночь при огне","text":"Третий день идёт дождь. Мы несли огонь на сухое место под пятью плащами и менялись на бегу. У меня прогорел рукав и немного рука. Хэмиш сказал, что так огонь благодарит. Я думаю, он просто горел. Но Хэмиш сам завязал мне руку тряпкой и долго ругался, так что я ему это прощаю.","chain":"nochnaya_ochered","part":3},{"id":"magma_044","kind":"note","title":"Запись о свадьбе","text":"Сегодня мы женили Кейт и Дэви. Слов для этого у нас ещё нет, поэтому Орин посмотрел на обоих и сказал: ну вот. Потом все пошли есть. Дэви плакал и говорил, что это от дыма. Кейт говорит, что запомнила и «ну вот», и дым."},{"id":"magma_045","kind":"note","title":"Родился тут","text":"Тэм родился уже здесь, и он единственный из нас, кто никуда не шёл. Старшие дети зовут его Гостем. Мать просит, чтобы кто-нибудь объяснил ему, когда он подрастёт, что такое дорога. Сама она не может, потому что начинает говорить и плачет."},{"id":"magma_046","kind":"note","title":"Запись о яме","text":"Я рыл яму под ячмень. На глубине локтя земля была тёплая, как хлеб из печи. На втором локте она стала такая горячая, что я перестал копать и всё засыпал. Всем, и жене тоже, я сказал, что в горшках ячмень сохраннее. Так им спокойнее спать."},{"id":"magma_047","kind":"note","title":"Жребий","text":"Мы тянули камешки на зиму, и чёрный камешек значит тёплое место. Длинный Гарт вытянул чёрный четвёртый раз подряд. Решили, что теперь он тянет первым, а руки ему будет держать Ида. Мои дети опять будут спать у холодной стены. Скажу им, что Гарт очень хорошо умеет тянуть.","chain":"teplaya_storona","part":3},{"id":"magma_048","kind":"note","title":"Про колодец","text":"Колодец сегодня тёплый, а вчера был холодный. Я набрала воды, и она пахнет как мокрый нож. Детям пока не давайте, а взрослым можно, они и не заметят. Особенно ты, Дэви, но ты всё равно пей поменьше, пожалуйста."},{"id":"magma_049","kind":"note","title":"Записка соседке","text":"Ренна, у вас стены тоже гудят по ночам? У нас они гудят негромко, как жук в горшке. Наша собака слушает, потом встаёт и ложится в другом месте, и скоро у неё кончатся места. Приходите к нам ночевать с детьми, если страшно. Если не страшно, всё равно приходите."},{"id":"magma_050","kind":"note","title":"Приписка","text":"Ида отдала эту глину Хобу за шесть лепёшек, и теперь Берт должен козу Хобу. Хоб не хочет козу, он хочет лепёшки обратно, но глину у него уже взяла Мод за воду. Берт ходит весёлый и говорит, что никогда ещё не был должен столько хорошим людям.","chain":"pervyi_dolg","part":4},{"id":"magma_051","kind":"note","title":"Про порог","text":"Я измерил порог, он ушёл вниз на палец. Левая половина дома теперь ниже, и наши горшки сами съезжают к соседке Ренне. Ренна довольна и говорит, что посуда знает, где её любят. Я подбил под стену клин. Вечером Ренна принесла горшки обратно, и в одном была каша."},{"id":"magma_052","kind":"note","title":"Записка у двери","text":"Кто увидит Джосса, скажите ему, что обед стоит у двери. Он ушёл к трещине посмотреть, откуда идёт тепло. Это было на прошлой неделе. Я каждый день ставлю ему новый обед, сегодня каша с салом, как он любит. Джосс, если ты читаешь это сам, я не сержусь."},{"id":"magma_053","kind":"note","title":"Записка Хэмишу","text":"Хэмиш! У нас двое детей, и ни одного из них ты ночью не укрывал. А к огню ты встаёшь три раза и накрываешь его от ветра. Ему от твоего одеяла только хуже, я проверяла. Дети спрашивают, когда ты придёшь домой. Я тоже спрашиваю."},{"id":"magma_054","kind":"note","title":"Закон об общем","text":"Каждую десятую лепёшку надо отдавать на общее. Что такое общее, нам показали: это горшок у камня. Горшок пуст, старший сыт, а спрашивать про это можно только по шестым дням. В прошлый шестой день я спросила. Орин покраснел, достал из-за пазухи лепёшку и отдал её моим детям."},{"id":"magma_055","kind":"note","title":"Дневник","text":"Мимо шли трое чужих и попросили воды. Мы дали. Один спросил, что это за место. Мы переглянулись, и Гарт сказал: город. До ночи мы ходили и смотрели, похоже ли. Один угол вроде похож, и Бет взяла меня за руку и долго там стояла."},{"id":"magma_056","kind":"note","title":"Письмо учителя","text":"Старшему от Осберта. Тринадцатого знака у меня нет. Дети просят показать, как написать, что брат умер. Я показал им черту, ту самую, из «нет хлеба». Тилли провела её рядом с именем брата и спросила, будет ли теперь хлеб. Я не знал, что ей ответить, и отдал ей свою лепёшку. Орин, придумай что-нибудь, мне нечем им это объяснить.","chain":"shkola_na_slance","part":3},{"id":"magma_057","kind":"note","title":"Мера горсти","text":"Теперь горсть у нас одна на всех, по руке Эдны. Её руку слепили из глины и положили у камня, чтобы мерить ячмень. Люди проходят мимо и жмут глиняную руку на удачу. Эдна говорит, что с неё хватит и что ей это не нравится, но по утрам сама ходит вытирать с руки пыль."},{"id":"magma_058","kind":"note","title":"Письмо сестре","text":"Сестра, мы остановились. Снизу идёт тепло, и плохо пахнет. Дом всё время стоит на одном месте, и мне всё хочется его куда-нибудь перенести. Эту глину я кладу у тропы, на камень с белой меткой, ты знаешь, как мы метили стоянки. Приходи, если найдёшь нас. Я всё ещё сплю на своей половине, а твоя пустая. Брида."},{"id":"magma_059","kind":"note","title":"Про деда","text":"Дед каждое утро собирает мешок, как тогда, когда мы ходили за стадом, а к вечеру разбирает. Мы ему ничего не говорим, мешок у него хороший. Вчера он положил туда и мою кружку. Значит, меня он всё ещё берёт с собой."},{"id":"magma_060","kind":"note","title":"Донос старшему","text":"Орин, я не люблю доносить, но Дункан ставит вторую стену, вокруг нашей. Камень он таскает по ночам, и камень этот наш. Вчера он спрашивал, не хочет ли кто переехать, потому что у него просторно. Двое ходили смотреть, и один из них был я. Там правда просторно. Он поставил нам две миски и всё спрашивал, не дует ли.","chain":"stena_dunkana","part":4},{"id":"magma_061","kind":"note","title":"Шутка Дорна","text":"Дорн опять рассказывал свою шутку. Гарт приходит к Гарту. Гарт спрашивает: ты кто? Гарт отвечает: Гарт. Тут надо подождать. Дорн ждёт очень долго, и в этом вся шутка. Оба Гарта её запретили, а жена Дорна смеётся каждый раз, хотя слышала её уже раз сорок."},{"id":"magma_062","kind":"note","title":"Кто лечит","text":"Если болит живот, идите к Альде. Если страшно, идите к Хобу, он умеет сидеть рядом. Зуб дёргает Рольф, верёвка у него есть, но привязывать будете сами."},{"id":"magma_063","kind":"note","title":"Счёт ячменя","text":"В горшке Эдны девять горстей ячменя, в горшке Рольфа четырнадцать. В общем горшке лежит одна горсть и мышь. Мышь не считаем. Дети просили её не выгонять, у неё там, оказывается, мышата."},{"id":"magma_064","kind":"note","title":"Ночь при огне","text":"Сегодня безветренно. Всякий огонь тянется вверх, а этот тянется туда, где трещина. Я поднесла щепку с другого бока, он поглядел на неё и повернулся обратно. Хэмишу я пока об этом не говорю, он и так плохо ест. Я положила ему в миску свою лепёшку, он съел и не заметил. Фрея.","chain":"nochnaya_ochered","part":4},{"id":"magma_065","kind":"note","title":"Карта на сланце","text":"Вот колодец. Вот трещина, туда не ходи. Вот дом Гвен. А вот ты, если стоишь у дома Гвен и читаешь это. Заходи, не стой, Гвен всех кормит."},{"id":"magma_066","kind":"note","title":"Правила игры","text":"Кто наступил на трещину, тот стал пеплом. Пепел лежит, пока ему не сосчитают до двадцати. Кто лёг без причины, пеплом не считается. Дети Гарта играют нечестно, с ними не играйте. Младшего можно взять, он ещё маленький и плачет, если его не берут."},{"id":"magma_067","kind":"note","title":"Записка мужу","text":"Ты опять таскал камень до темноты и опять за едой рассказывал про угол. Я не знаю, что такое угол, и слушаю тебя только потому, что ты при этом улыбаешься. Суп стоит на горячем камне. Поешь и ложись, пожалуйста, ты совсем худой."},{"id":"magma_068","kind":"note","title":"Вторая приписка","text":"Теперь глина у Кенрика, ему отдали её за крышу. Прочесть её он не может, но говорят, что там про козу. Завтра он отдаст её Гвен за сало. Кто кому должен, все уже забыли, а глину берут охотно. Коза давно умерла от старости. Ида с Бертом закопали её вместе и поругались над ямой, как в лучшие годы.","chain":"pervyi_dolg","part":5},{"id":"magma_069","kind":"note","title":"Про Рольфа","text":"Рольф придумал запираться. Дверь у него теперь закрывается изнутри на палку. Вчера он закрылся, палку заклинило, а как открыть, он не придумал. Жена кормит его через окно. Окно пришлось сделать вчера же. Она говорит, что ей так нравится: муж дома, а спорить неудобно."},{"id":"magma_070","kind":"note","title":"Первая строка","text":"Мне шестьдесят лет, и я пишу первый раз. Вот знак: вода. Осберт посмотрел и спросил, откуда тут собака. Я рисовала долго и переделывать не буду. Внук сказал, что собака хорошая."},{"id":"magma_071","kind":"secret","title":"Письмо в нише","text":"Тому, кто будет тут жить после нас. Правый колодец горький, не пей из него, а левый хороший. Крышу у моего дома чинить не надо, она так и задумана. Жена ругала эту крышу до самой смерти, и я ни разу её не поправил, потому что любил, как она ругается. Будь здоров, кто бы ты ни был."},{"id":"magma_072","kind":"secret","title":"Про ступень","text":"Мы копали яму под домом старшего и нашли ступень, тёсаную. Ниже нашли ещё одну. Мы шли сюда сорок дней и пришли первые. На сходе договорились, что первые, и ступень засыпали. Я пишу это здесь, потому что детям я сказал то же самое, и мне от этого нехорошо."},{"id":"magma_073","kind":"secret","title":"Уголёк","text":"Говорят, что огонь не гас с тех пор, как его принесли. Он гас три раза. Я зажигала его снова от уголька, который лежит тут, в горшке с песком. Хэмишу я не скажу никогда, он так им гордится, и пусть гордится, он уже старый. Огонь-то всё равно тот же. Фрея."},{"id":"magma_074","kind":"secret","title":"Чужие знаки","text":"Эти знаки мы придумали с Тилли, кроме нас двоих их никто не прочтёт, так что пишу как есть. Хоб дурак. Его нож лежит у меня под камнем. Гвен нравится Вилл. Тилли, ты лучше всех, только не задавайся."},{"id":"magma_075","kind":"secret","title":"Карта ухода","text":"До старой стоянки четыре дня, если идти по ручью. Я рисую эту карту, чтобы уйти отсюда. Рисую третий год и всё поправляю ручей. На этой неделе уйти не получится, у младшей режется зуб. Муж про карту не знает. Он каждый вечер приносит мне воды и спрашивает, что я там царапаю, и я говорю, что ручей."},{"id":"magma_076","kind":"secret","title":"Кто у трещины","text":"Записываю, потому что мне никто не верит. Мы шли сорок дней и пришли сюда первые. А у трещины на камне уже сидел человек и грел руки. Он спросил, чего мы так долго. Каждая семья подумала, что он из другой семьи. Он и сейчас там сидит, и дети носят ему хлеб. Жена говорит, что я выдумываю, и кладёт мне каши побольше."},{"id":"magma_077","kind":"secret","title":"Признание","text":"Гуся взял я. Фиска судили за это, и он держался хорошо, дольше, чем смог бы я. Гусь, если кому интересно, был жёсткий. Фиск, ты ни разу не сказал, что видел меня. Я знаю, что ты видел. Рэн."},{"id":"magma_078","kind":"secret","title":"Про жребий","text":"Чёрные камешки мы с Длинным Гартом держим у очага всю ночь. В темноте рука сама находит тёплый. У него дети кашляют, и у меня кашляют. Другому Гарту об этом ни слова, он хороший человек и сразу всем расскажет."},{"id":"magma_079","kind":"secret","title":"Детской рукой","text":"это моё место. тут никто не ходит. снизу тепло и я ложусь ухом и слышу оно дышит. оно дышит медленно. дольше чем папа когда спит. я рассказываю ему про собаку. маме не скажу а то заберёт меня домой"},{"id":"magma_080","kind":"secret","title":"Про трещину","text":"Я мерил трещину верёвкой и никому об этом не сказал. За год она разошлась на длину руки. Дома мы только поставили, люди радуются, у Кейт родился второй, и она принесла мне его подержать. Я подержал и улыбался. Верёвку храню здесь, узел завязан на прошлогодней мерке."},{"id":"magma_081","kind":"boss","title":"Жалоба улицы","text":"Старшему от всей улицы. Каменщик опять поёт и начинает до света. Слов он не знает и вместо них называет камни, какой куда класть. Нота у него одна, и та чужая. Просим перенести пение на тот конец, где козы. С козами мы договорились. Только не говори ему, что это мы, он обидится, а он нам всем дома ставил.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_082","kind":"boss","title":"Детской рукой","text":"мой папа самый громкий. он носит камень на спине а меня на камне. когда он поёт тётя Эдна закрывает дверь. у неё дверь первая у нас. папа её и делал. он говорит пусть закрывает дверь хорошая","boss":"boss_colossus","floors":[13,16]},{"id":"magma_083","kind":"boss","title":"Записка соседки","text":"Ренна, каменщику выпала тёплая сторона, а он отдал её старой Мод и лёг у двери. Всю ночь он жаловался, что дует, и жаловался громко, чтобы все слышали, как ему холодно. Ему всегда холодно. Я отнесла ему шкуру, в эту зиму уже третью. Куда он их девает, я знаю: две теперь лежат у Мод.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_084","kind":"boss","title":"Расписка","text":"За подпорку под домом Орина получен мешок ячменя. Каменщик ячмень взял, потом вернул половину и сказал, что подпорка вышла так себе. Если дом осядет, пусть зовут его, он подопрёт плечом, так выйдет дешевле. Орин велел мне, жене, это записать. Я пишу и смеюсь, а Орин говорит: не смейся, этот придёт.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_085","kind":"boss","title":"Школьное задание","text":"Напиши, что умеет твой отец. Мой папа умеет поднять двух коз сразу. Ещё он умеет делать угол. Петь он не умеет, но мы ему не говорим. Меня он никогда не роняет. Нэн.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_086","kind":"boss","title":"Нэн, на сланце","text":"нас вела тётя Ренна всех на одной верёвке. было темно и пыль. папа стоял там где потолок шёл вниз. он сказал идите и что ему не тяжело. он пел как всегда плохо и я долго его слышала. тётя сказала не оборачивайся но слышать же можно","boss":"boss_colossus","floors":[13,16]},{"id":"magma_087","kind":"boss","title":"Список выведенных","text":"Мы вывели по верёвке Нэн, Робина, обоих мальчиков Длинного Гарта, Тилли с младшей и младенца Эдны, а всего двадцать три человека. Мы считали дважды, потом Эдна пересчитала сама, потому что не поверила. Всем дать воды и уложить спать. Верёвка эта каменщика, положите её ему на порог, он будет ругаться, если потеряем.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_088","kind":"boss","title":"Записка Ренны","text":"Нэн не спит и просит папину песню. Мы пели ей всей улицей. Слов никто не знает, там одни камни, какой куда. У Дорна вышло слишком хорошо, и она велела ему перестать. Гарт поёт хуже всех, и мы оставили Гарта. Он поёт ей уже четвёртую ночь и охрип. Наверное, за её отцом кто-то уже сходил. Завтра спрошу.","boss":"boss_colossus","floors":[13,16]},{"id":"pilot_001","kind":"note","title":"Список покупок","text":"Милый, купи соли и верёвки. Свечи бери, если дадут в долг. Верёвки возьми побольше, та, что ты принёс, оказалась короткая и не достала до дна. Мазь от укусов тоже не забудь. И скажи Тому, чтобы спал наверху. Меня он не слушает, а тебя, может быть, послушает, и я за него боюсь."},{"id":"pilot_002","kind":"note","title":"Жалоба соседу","text":"Господин Брейн! Ваши бочки стоят на моей половине подвала уже третий год. Если к воскресенью они не уедут, я напишу старосте, и не думайте, что не напишу, я вас двадцать лет терплю. Прошу также объяснить, почему одна из них ночью передвинулась. Если это вы сами ходите туда двигать её мне назло, я, так и быть, успокоюсь. Если не вы, зайдите, пожалуйста, мне страшно, а больше позвать некого."},{"id":"pilot_003","kind":"note","title":"Детской рукой","text":"я нашол дверцу за мешками. там ещё лестница вниз. мама сказала там ничего нет. а откуда она знает если она не ходила. я схожу посмотрю и ей расскажу чтобы она не боялась"},{"id":"pilot_004","kind":"note","title":"Рецепт","text":"Дорогая Элла, вот мамин рецепт капусты на зиму, ты просила. Сложи кочаны в кадку, всыпь четыре горсти соли и поставь сверху гнёт. Через месяц капуста будет готова. Гнёт не снимай, пока кадка шевелится. Мама всегда так говорила, и мы с тобой над ней смеялись, а зря. Поцелуй за меня детей."},{"id":"pilot_005","kind":"note","title":"Записка мужу","text":"Я ушла к сестре и детей забрала с собой. Тебе я оставила хлеб на полке и тёплую куртку. Ты опять скажешь, что копать осталось ещё один пролёт и мы разбогатеем. Я сама слышала, Мартин, как из твоей ямы кто-то зовёт тебя по имени. Я тебя люблю, поэтому и ухожу. Приходи к нам, когда перестанешь копать."},{"id":"pilot_006","kind":"note","title":"Расписка","text":"Я, Ольрик Панч, должен пекарю Хэлу четыре монеты и извинения. Монеты отдам к празднику. Извинения отдам, когда перестану злиться, то есть, зная нас обоих, к следующему. Мы с Хэлом дружим сорок лет, и он знает, что я отдам всё."},{"id":"pilot_007","kind":"note","title":"Табличка на стене","text":"Паутину не трогайте, она держит потолок. Когда Дженкинсы смахнули свою метлой, потолок сел им на шкаф. Это приказ старосты, а от себя прошу вас, соседи, поберегите детей."},{"id":"pilot_008","kind":"note","title":"Объявление","text":"Ищу кота. Он рыжий, с одним ухом и откликается на Судью. Кто его найдёт, пусть не берёт на руки и сразу идёт к лекарю, потому что с тех пор, как он пожил в подвале, у него ядовитый укус. Я вырастил его из котёнка, за ужином он сидит на моём стуле, и без него мне пусто в доме. За кота заплачу две монеты, за лекаря тоже."},{"id":"pilot_009","kind":"note","title":"Записка у ниши","text":"Элис, милая, я вырезал нам скамейку у колодца, как ты хотела. Сядем на неё, когда потеплеет. Плащ я оставил в нише за второй бочкой. Прошлый хлеб ты забрала, и я обрадовался. Мне всё равно, какая ты теперь. Ты так и не сказала, холодно ли тебе там внизу, скажи только это, и я принесу ещё один плащ."},{"id":"pilot_010","kind":"note","title":"Журнал сторожа","text":"Идёт первая неделя на складе. Платят хорошо, и работа простая: утром и вечером считать мешки. Утром их было сорок, а вечером оказался сорок один. Я спросил у хозяина, и он велел считать внимательнее. Журнал я веду, потому что сестра говорит, что память у меня дырявая. Мэй, если читаешь, со мной всё хорошо, деньги пришлю к концу месяца.","chain":"watchman","part":1},{"id":"pilot_011","kind":"note","title":"Журнал сторожа","text":"Сегодня мешков сорок семь, и один из них тёплый. Хозяин больше не спускается сюда, а деньги оставляет на лестнице. Мэй, я хотел отказаться от места, но эти деньги пойдут на твою свадьбу, так что потерплю. Ты не волнуйся, я сплю с лампой и в мешки не заглядываю.","chain":"watchman","part":2},{"id":"pilot_012","kind":"note","title":"Журнал сторожа","text":"Теперь я считаю вслух, чтобы не сбиться. Сегодня кто-то считает вместе со мной, и получается у него лучше. Голос у него вежливый, он меня поправляет. Деньги я сложил в жестянку за дверью склада. Мэй, если к празднику я не приду, забери их, выходи за своего Питера и не ходи сюда меня искать. Я очень по тебе скучаю.","chain":"watchman","part":3},{"id":"pilot_013","kind":"secret","title":"Записка из тайника","text":"Если ты это читаешь, значит, ты нашёл мой тайник, а денег тут больше нет, я их потратил. На жену, если тебе от этого легче: она всю жизнь хотела синюю шаль. Это моя третья такая записка. Мне нравится думать, что кто-то ищет, и тогда мы с тобой, дружище, вроде как знакомы."},{"id":"pilot_014","kind":"secret","title":"Записка из тайника","text":"Каменщик из соседнего квартала клянётся, что кладка под нашей улицей точно такая же, как наверху: те же клейма и та же рука. Я попросил его больше так не шутить, у меня дети. Он ответил, что не шутил, а потом долго молчал и налил нам обоим. Мы дружим с ученичества, и я ни разу не видел, чтобы у него так дрожала рука."}];
})(typeof window !== 'undefined' ? window : globalThis);
